INSERT INTO `assignments` (`id`, `category`, `title`, `subtitle`, `description`, `theory_equations`, `parameters`, `starter_code`, `solution_code`, `created_at`, `updated_at`) VALUES
('1', 'mechanics', 'Projectile Motion with Quadratic Air Drag', 'Model aerodynamic deceleration using coupled ODEs', 'Model the trajectory of a spherical projectile under the influence of gravity and non-linear aerodynamic air resistance.', '$$\\frac{dx}{dt} = v_x, \\quad \\frac{dv_x}{dt} = -\\frac{c}{m} v_x \\sqrt{v_x^2 + v_y^2}$$\\n$$\\frac{dy}{dt} = v_y, \\quad \\frac{dv_y}{dt} = -g -\\frac{c}{m} v_y \\sqrt{v_x^2 + v_y^2}$$', 'Mass $m = 0.145\\text{ kg}$, initial speed $v_0 = 45\\text{ m/s}$, launch angle $\\theta = 45^\\circ$, drag constant $c = 0.0015\\text{ kg/m}$, $g = 9.81\\text{ m/s}^2$.', 'import numpy as np\nimport matplotlib.pyplot as plt\n\nm = 0.145\ng = 9.81\nc = 0.0015\nv0 = 45.0\ntheta = np.radians(45)\n\ndt = 0.001\nx, y = [0.0], [0.0]\nvx, vy = [v0 * np.cos(theta)], [v0 * np.sin(theta)]\n\nwhile y[-1] >= 0:\n    v = np.sqrt(vx[-1]**2 + vy[-1]**2)\n    ax = -(c/m) * v * vx[-1]\n    ay = -g - (c/m) * v * vy[-1]\n    vx.append(vx[-1] + ax * dt)\n    vy.append(vy[-1] + ay * dt)\n    x.append(x[-1] + vx[-1] * dt)\n    y.append(y[-1] + vy[-1] * dt)\n\nR_vac = (v0**2 * np.sin(2*theta)) / g\nprint(f\"Vacuum Range: {R_vac:.2f} m\")\nprint(f\"Realistic Range (Drag): {x[-1]:.2f} m\")\n\nplt.figure(figsize=(7, 3.8))\nplt.plot(x, y, label=\'With Quadratic Drag\', color=\'#06b6d4\', lw=2)\nplt.title(\'Projectile Motion with Air Drag\')\nplt.xlabel(\'Distance (m)\')\nplt.ylabel(\'Height (m)\')\nplt.grid(True, alpha=0.3)\nplt.legend()\nplt.show()', '', '2026-09-22 16:28:18', '2026-09-22 16:28:18'),
('2', 'electrodynamics', 'Electric Field & Equipotential Contours of an Electric Quadrupole', '2D electrostatic field line integration and potential mesh computation', 'Calculate and visualize the 2D electrostatic potential field $\\Phi(x, y)$ and field vector gradient $\\vec{E} = -\\nabla \\Phi$ for an arrangement of four point charges in a planar quadrupole configuration.', '$$\\Phi(\\vec{r}) = \\frac{1}{4\\pi \\varepsilon_0} \\sum_{i=1}^{N} \\frac{q_i}{|\\vec{r} - \\vec{r}_i|}, \\quad \\vec{E} = -\\nabla \\Phi = -\\left( \\frac{\\partial \\Phi}{\\partial x} \\hat{i} + \\frac{\\partial \\Phi}{\\partial y} \\hat{j} \\right)$$', 'Charges $q = \\pm 1\\text{ nC}$ placed at $(1, 1), (-1, 1), (-1, -1), (1, -1)$. Mesh resolution $200 \\times 200$.', 'import numpy as np\nimport matplotlib.pyplot as plt\n\nx = np.linspace(-3, 3, 200)\ny = np.linspace(-3, 3, 200)\nX, Y = np.meshgrid(x, y)\n\ncharges = [\n    {\'q\':  1.0, \'pos\': ( 1.0,  1.0)},\n    {\'q\': -1.0, \'pos\': (-1.0,  1.0)},\n    {\'q\':  1.0, \'pos\': (-1.0, -1.0)},\n    {\'q\': -1.0, \'pos\': ( 1.0, -1.0)},\n]\n\nV = np.zeros_like(X)\nfor c in charges:\n    r = np.sqrt((X - c[\'pos\'][0])**2 + (Y - c[\'pos\'][1])**2)\n    r = np.maximum(r, 0.15)\n    V += c[\'q\'] / r\n\nEy, Ex = np.gradient(-V, y, x)\n\nplt.figure(figsize=(7, 4.5))\nplt.contourf(X, Y, V, levels=30, cmap=\'RdBu_r\', alpha=0.7)\nplt.colorbar(label=\'Potential V (arb. units)\')\nplt.streamplot(X, Y, Ex, Ey, color=\'black\', density=0.9, linewidth=0.7)\nplt.title(\'Quadrupole Potential & Electric Field Lines\')\nplt.xlabel(\'x\')\nplt.ylabel(\'y\')\nplt.show()', '', '2026-09-22 16:28:18', '2026-09-22 16:28:18'),
('3', 'quantum', 'Finite Square Well: Bound State Energies via Transcendental Bisection', 'Numerical root finding for symmetric and antisymmetric quantum wavefunctions', 'Determine the bound-state energy eigenvalues for a particle of mass $m$ trapped inside a finite 1D square potential well of width $2a$ and depth $V_0$.', '$$\\xi \\tan \\xi = \\sqrt{\\xi_0^2 - \\xi^2} \\quad \\text{(Even Parity)}, \\quad -\\xi \\cot \\xi = \\sqrt{\\xi_0^2 - \\xi^2} \\quad \\text{(Odd Parity)}$$\\n$$\\text{where } \\xi = \\frac{a}{\\hbar}\\sqrt{2m(E + V_0)}, \\quad \\xi_0 = \\frac{a}{\\hbar}\\sqrt{2m V_0}$$', 'Well half-width $a = 1.0\\text{ nm}$, Well depth $V_0 = 10.0\\text{ eV}$, electron mass $m_e$.', 'import numpy as np\nfrom scipy.optimize import brentq\nimport matplotlib.pyplot as plt\n\nV0 = 10.0 # eV\na = 1.0e-9 # m\nhbar = 1.0545718e-34\nm = 9.10938356e-31\ne = 1.60217663e-19\n\nxi0 = (a / hbar) * np.sqrt(2 * m * V0 * e)\nprint(f\"Dimensionless parameter xi_0 = {xi0:.3f}\")\n\ndef even_eq(xi):\n    return xi * np.tan(xi) - np.sqrt(xi0**2 - xi**2)\n\nroots = []\nxi_vals = np.linspace(0.01, min(xi0 - 0.01, 3*np.pi), 500)\nfor i in range(len(xi_vals)-1):\n    x1, x2 = xi_vals[i], xi_vals[i+1]\n    if np.cos(x1)*np.cos(x2) > 0 and even_eq(x1)*even_eq(x2) < 0:\n        try:\n            r = brentq(even_eq, x1, x2)\n            roots.append(r)\n        except:\n            pass\n\nprint(f\"Found {len(roots)} even bound states:\")\nfor idx, r in enumerate(roots, 1):\n    E_bound = (r / xi0)**2 * V0 - V0\n    print(f\"  E_{idx} = {E_bound:.3f} eV\")', '', '2026-09-22 16:28:18', '2026-09-22 16:28:18'),
('4', 'thermo', '2D Ising Model Monte Carlo via Metropolis Algorithm', 'Spontaneous symmetry breaking, magnetization, and phase transition simulation', 'Simulate the magnetic phase transition in a 2D ferromagnetic square lattice using the Metropolis Monte Carlo algorithm.', '$$\\mathcal{H} = -J \\sum_{\\langle i, j \\rangle} s_i s_j, \\quad \\Delta E = 2 J s_i \\sum_{\\text{neighbors}} s_j$$\\n$$P(\\text{flip}) = \\min\\left(1, e^{-\\Delta E / k_B T}\\right)$$', 'Lattice size $L = 32 \\times 32$, Coupling $J = 1.0$, $T_c \\approx 2.269$.', 'import numpy as np\nimport matplotlib.pyplot as plt\n\nL = 32\nN_steps = 15000\nT = 2.0\n\nspins = np.random.choice([-1, 1], size=(L, L))\n\ndef step(spins, T):\n    for _ in range(L * L):\n        i = np.random.randint(0, L)\n        j = np.random.randint(0, L)\n        s = spins[i, j]\n        nb = spins[(i+1)%L, j] + spins[(i-1)%L, j] + spins[i, (j+1)%L] + spins[i, (j-1)%L]\n        dE = 2 * s * nb\n        if dE <= 0 or np.random.rand() < np.exp(-dE / T):\n            spins[i, j] = -s\n    return spins\n\nfor _ in range(50):\n    spins = step(spins, T)\n\nplt.figure(figsize=(5, 5))\nplt.imshow(spins, cmap=\'coolwarm\', interpolation=\'nearest\')\nplt.title(f\'2D Ising Lattice at T = {T:.2f}\')\nplt.colorbar(ticks=[-1, 1], label=\'Spin Orientation\')\nplt.axis(\'off\')\nplt.show()', '', '2026-09-22 16:28:18', '2026-09-22 16:28:18');
