INSERT INTO `gnuplot` (`id`, `menu_id`, `submenu_id`, `program_id`, `content`, `algo`, `explanation`, `output`) VALUES
('1', '1', '1', '1', 'set terminal png size 800,600\r\nset output \'plot1.png\'\r\nset title \'Simple Line Plot\'\r\nset xlabel \'X-axis\'\r\nset ylabel \'Y-axis\'\r\nplot x title \'y = x\' with lines', '', '<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<style>\r\n    table {\r\n        width: 100%;\r\n        \r\n    }\r\n\r\n    th, td {\r\n        word-wrap: break-word;\r\n        white-space: normal;\r\n        overflow-wrap: break-word; /* Allows long words to wrap */\r\n    }\r\n\r\n</style>\r\n\r\n\r\n\r\n    \r\n    <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n    <h2>Math Library Functions</h2>\r\n    <table border=\"4\" cellpadding=\"5\" cellspacing=\"0\" style=\"width: 100%;\">\r\n        <thead>\r\n            <tr>\r\n                <th>Function</th>\r\n                <th>Arguments</th>\r\n                <th>Returns</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            <tr>\r\n                <td>abs(x)</td>\r\n                <td>any</td>\r\n                <td>\\(|x|\\), absolute value of \\( x \\); same type</td>\r\n            </tr>\r\n            <tr>\r\n                <td>abs(x)</td>\r\n                <td>complex</td>\r\n                <td>\\(\\sqrt{\\text{real}(x)^2 + \\text{imag}(x)^2}\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>acos(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\cos^{-1}(x)\\) (inverse cosine)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>acosh(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\cosh^{-1}(x)\\) (inverse hyperbolic cosine)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>airy(x)</td>\r\n                <td>any</td>\r\n                <td>Airy function \\( \\text{Ai}(x) \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>arg(x)</td>\r\n                <td>complex</td>\r\n                <td>the phase of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>asin(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\sin^{-1}(x)\\) (inverse sine)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>asinh(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\sinh^{-1}(x)\\) (inverse hyperbolic sine)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>atan(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\tan^{-1}(x)\\) (inverse tangent)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>atan2(y, x)</td>\r\n                <td>int or real</td>\r\n                <td>\\(\\tan^{-1}(y/x)\\) (inverse tangent)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>atanh(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\tanh^{-1}(x)\\) (inverse hyperbolic tangent)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>EllipticK(k)</td>\r\n                <td>real \\( k \\in (-1:1) \\)</td>\r\n                <td>\\(K(k)\\), complete elliptic integral of the first kind</td>\r\n            </tr>\r\n            <tr>\r\n                <td>EllipticE(k)</td>\r\n                <td>real \\( k \\in [-1:1] \\)</td>\r\n                <td>\\(E(k)\\), complete elliptic integral of the second kind</td>\r\n            </tr>\r\n            <tr>\r\n                <td>EllipticPi(n, k)</td>\r\n                <td>real \\( n < 1 \\), real \\( k \\in (-1:1) \\)</td>\r\n                <td>\\(\\Pi(n, k)\\), complete elliptic integral of the third kind</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besj0(x)</td>\r\n                <td>int or real</td>\r\n                <td>\\(J_0\\), Bessel function of \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besj1(x)</td>\r\n                <td>int or real</td>\r\n                <td>\\(J_1\\), Bessel function of \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besjn(n, x)</td>\r\n                <td>int, real</td>\r\n                <td>\\(J_n\\), Bessel function of \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besy0(x)</td>\r\n                <td>int or real</td>\r\n                <td>\\(Y_0\\), Bessel function of \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besy1(x)</td>\r\n                <td>int or real</td>\r\n                <td>\\(Y_1\\), Bessel function of \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besyn(n, x)</td>\r\n                <td>int, real</td>\r\n                <td>\\(Y_n\\), Bessel function of \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besi0(x)</td>\r\n                <td>real</td>\r\n                <td>Modified Bessel function of order \\( 0 \\), \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besi1(x)</td>\r\n                <td>real</td>\r\n                <td>Modified Bessel function of order \\( 1 \\), \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>besin(n, x)</td>\r\n                <td>int, real</td>\r\n                <td>Modified Bessel function of order \\( n \\), \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>ceil(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\lceil x \\rceil\\), smallest integer not less than \\( x \\) (real part)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>cos(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\cos(x)\\), cosine of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>cosh(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\cosh(x)\\), hyperbolic cosine of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>erf(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\text{erf(real}(x))\\), error function of \\(\\text{real}(x)\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>erfc(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\text{erfc(real}(x))\\), \\(1.0 - \\) error function of \\(\\text{real}(x)\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>exp(x)</td>\r\n                <td>any</td>\r\n                <td>\\(e^x\\), exponential function of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>expint(n, x)</td>\r\n                <td>int \\( n \\geq 0 \\), real \\( x \\geq 0 \\)</td>\r\n                <td>\\(E_n(x) = \\int_1^{\\infty} t^{-n} e^{-xt} \\, dt\\), exponential integral of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>floor(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\lfloor x \\rfloor\\), largest integer not greater than \\( x \\) (real part)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>gamma(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\text{gamma(real}(x))\\), gamma function of \\(\\text{real}(x)\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>ibeta(p, q, x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\text{ibeta}(p, q, x)\\), beta function of \\( (p, q, x) \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>inverf(x)</td>\r\n                <td>any</td>\r\n                <td>inverse error function of \\(\\text{real}(x)\\)</td>\r\n            </tr>\r\n\r\n            <tr>\r\n                <td>igamma(a, x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\text{igamma(real}(a, x))\\), igamma function of \\(\\text{real}(a, x)\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>imag(x)</td>\r\n                <td>complex</td>\r\n                <td>imaginary part of \\( x \\) as a real number</td>\r\n            </tr>\r\n            <tr>\r\n                <td>invnorm(x)</td>\r\n                <td>any</td>\r\n                <td>inverse normal distribution function of \\(\\text{real}(x)\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>int(x)</td>\r\n                <td>real</td>\r\n                <td>integer part of \\( x \\), truncated toward zero</td>\r\n            </tr>\r\n            <tr>\r\n                <td>lambertw(x)</td>\r\n                <td>real</td>\r\n                <td>Lambert \\( W \\) function</td>\r\n            </tr>\r\n            <tr>\r\n                <td>lgamma(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\text{lgamma(real}(x))\\), lgamma function of \\(\\text{real}(x)\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>log(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\log_e x\\), natural logarithm (base \\( e \\)) of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>log10(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\log_{10} x\\), logarithm (base 10) of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>norm(x)</td>\r\n                <td>any</td>\r\n                <td>normal distribution (Gaussian) function of \\(\\text{real}(x)\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>rand(x)</td>\r\n                <td>int</td>\r\n                <td>pseudo random number in the open interval \\((0:1)\\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>real(x)</td>\r\n                <td>any</td>\r\n                <td>real part of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>sgn(x)</td>\r\n                <td>any</td>\r\n                <td>\\(1\\) if \\( x > 0 \\), \\(-1\\) if \\( x < 0 \\), \\(0\\) if \\( x = 0 \\). \\(\\text{imag}(x)\\) ignored</td>\r\n            </tr>\r\n            <tr>\r\n                <td>sin(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\sin x\\), sine of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>sinh(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\sinh x\\), hyperbolic sine of \\( x \\) in radians</td>\r\n            </tr>\r\n            <tr>\r\n                <td>sqrt(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\sqrt{x}\\), square root of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>tan(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\tan x\\), tangent of \\( x \\)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>tanh(x)</td>\r\n                <td>any</td>\r\n                <td>\\(\\tanh x\\), hyperbolic tangent of \\( x \\) in radians</td>\r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n\r\n', NULL),
