('24', '2', '1', '4', '#Plotting a Complex Function in GNUplot\r\nset terminal png size 400, 300\r\nset output \'complex_function.png\'\r\n\r\n# Set the title and labels\r\nset title \"Complex Function: f(x) = e^(ix)\"\r\nset xlabel \"X-axis\"\r\nset ylabel \"Y-axis\"\r\nset grid\r\n\r\n# Define a complex function f(x) = e^(ix)\r\nf_real(x) = cos(x)     # Real part: cos(x)\r\nf_imag(x) = sin(x)     # Imaginary part: sin(x)\r\nf_magnitude(x) = sqrt(f_real(x)**2 + f_imag(x)**2)  # Magnitude: |e^(ix)|\r\nf_phase(x) = atan2(f_imag(x), f_real(x))            # Phase: arg(e^(ix))\r\n\r\n# Plot the real part, imaginary part, magnitude, and phase of the complex function\r\nplot f_real(x) with lines lw 2 title \'Re:cos(x)\', \\\r\n     f_imag(x) with lines lw 2 title \'Im:sin(x)\', \\\r\n     f_magnitude(x) with lines lw 2 title \'Magnitude\', \\\r\n     f_phase(x) with lines lw 2 title \'Phase\'', '', '', NULL),
('25', '2', '1', '5', '#Function plot: double y axis\r\nset terminal png size 400, 300\r\nset output \'plot.png\'\r\nset xrange [-10:10]\r\nset yrange [-1:5]\r\nset y2range [-1:3]\r\nset ylabel \"f(x)\"\r\nset y2label \"g(x)\"\r\nset title \"double y axis plot\"\r\nset xtics -10, 2, 10\r\nset ytics -1, 1, 5\r\nset y2tics -1, 1, 5\r\nplot  x**2 axis x1y1 w p title \'f(x)\', exp(-x**2/2) axis x1y2 w lp title \'gf(x)\'', '', '', NULL),
('26', '2', '1', '6', '#Iterative plot\r\nset terminal png size 400, 300\r\nset output \'plot.png\'\r\nset xrange [-10:10]\r\nset ylabel \"f(x)\"\r\nset title \"Iteration\"\r\nset xtics -10, 2, 10\r\nplot  for [i = 1:4] i*x+3 lw 2', '', '', NULL),
('27', '2', '1', '7', '#Multiplot\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\nset multiplot\r\n\r\nset size 0.5 , 0.5\r\n\r\nset origin 0,0\r\npl sin(x)\r\n\r\nset origin 0,0.5 \r\npl x**2 w p\r\n\r\nset origin 0.5,0\r\npl exp(-x**2/2) w lp\r\n\r\nset origin 0.5,0.5\r\npl tan(x)', '', '', NULL),
('28', '2', '2', '1', '#Piece-wise Function Plot\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\n#f(x) = x**2 for x>0 and f(x) = x otherwise\r\nf(x) =(x>0)? x**2 : x\r\npl f(x) w lp lw 2', '\r\n    \r\n    <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n\r\n<h4>Piecewise Function</h4>\r\n<p>Plot a piecewise function where:</p>\r\n\r\n<p>\r\n\\[\r\nf(x) = \r\n\\begin{cases} \r\nx^2 & \\text{if } x > 0 \\\\ \r\nx & \\text{otherwise}\r\n\\end{cases}\r\n\\]\r\n</p>', '\r\n<style>\r\n    table {\r\n        width: 100%;\r\n        \r\n    }\r\n\r\n    th, td {\r\n        word-wrap: break-word;\r\n        white-space: normal;\r\n		text-align: center;\r\n        overflow-wrap: break-word; /* Allows long words to wrap */\r\n    }\r\n\r\n</style>\r\n\r\n\r\n\r\n    \r\n    <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n    <h2>Unary Operators</h2>\r\n<table border=\"4\" cellpadding=\"5\" cellspacing=\"0\" style=\"width: 100%;\">\r\n    <thead>\r\n        <tr>\r\n            <th>Symbol</th>\r\n            <th>Example</th>\r\n            <th>Explanation</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>-</td>\r\n            <td>\\(-a\\)</td>\r\n            <td>unary minus</td>\r\n        </tr>\r\n        <tr>\r\n            <td>+</td>\r\n            <td>\\(+a\\)</td>\r\n            <td>unary plus (no-operation)</td>\r\n        </tr>\r\n        <tr>\r\n            <td>~</td>\r\n            <td>\\(~a\\)</td>\r\n            <td>one\'s complement</td>\r\n        </tr>\r\n        <tr>\r\n            <td>!</td>\r\n            <td>\\(!a\\)</td>\r\n            <td>logical negation</td>\r\n        </tr>\r\n        <tr>\r\n            <td>!</td>\r\n            <td>\\(a!\\)</td>\r\n            <td>factorial</td>\r\n        </tr>\r\n        <tr>\r\n            <td>$</td>\r\n            <td>\\($3\\)</td>\r\n            <td>call arg/column during \'using\' manipulation</td>\r\n        </tr>\r\n        <tr>\r\n            <td>\\(|\\)</td>\r\n            <td>\\(|A|\\)</td>\r\n            <td>cardinality of array \\( A \\)</td>\r\n        </tr>\r\n    </tbody>\r\n</table >\r\n<h2>Binary Operators</h2>\r\n\r\n<table border=\"4\" cellpadding=\"5\" cellspacing=\"0\" style=\"width: 100%;\">\r\n  <tr>\r\n    <th>Symbol</th>\r\n    <th>Example</th>\r\n    <th>Explanation</th>\r\n  </tr>\r\n  <tr>\r\n    <td>**</td>\r\n    <td>a**b</td>\r\n    <td>exponentiation</td>\r\n  </tr>\r\n  <tr>\r\n    <td>*</td>\r\n    <td>a*b</td>\r\n    <td>multiplication</td>\r\n  </tr>\r\n  <tr>\r\n    <td>/</td>\r\n    <td>a/b</td>\r\n    <td>division</td>\r\n  </tr>\r\n  <tr>\r\n    <td>%</td>\r\n    <td>a%b</td>\r\n    <td>modulo</td>\r\n  </tr>\r\n  <tr>\r\n    <td>+</td>\r\n    <td>a+b</td>\r\n    <td>addition</td>\r\n  </tr>\r\n  <tr>\r\n    <td>-</td>\r\n    <td>a-b</td>\r\n    <td>subtraction</td>\r\n  </tr>\r\n  <tr>\r\n    <td>==</td>\r\n    <td>a==b</td>\r\n    <td>equality</td>\r\n  </tr>\r\n  <tr>\r\n    <td>!=</td>\r\n    <td>a!=b</td>\r\n    <td>inequality</td>\r\n  </tr>\r\n  <tr>\r\n    <td><</td>\r\n    <td>a<b</td>\r\n    <td>less than</td>\r\n  </tr>\r\n  <tr>\r\n    <td><=</td>\r\n    <td>a<=b</td>\r\n    <td>less than or equal to</td>\r\n  </tr>\r\n  <tr>\r\n    <td>></td>\r\n    <td>a>b</td>\r\n    <td>greater than</td>\r\n  </tr>\r\n  <tr>\r\n    <td>>=</td>\r\n    <td>a>=b</td>\r\n    <td>greater than or equal to</td>\r\n  </tr>\r\n  <tr>\r\n    <td><<</td>\r\n    <td>0xff<<1</td>\r\n    <td>left shift unsigned</td>\r\n  </tr>\r\n  <tr>\r\n    <td>>></td>\r\n    <td>0xff>>1</td>\r\n    <td>right shift unsigned</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&</td>\r\n    <td>a&b</td>\r\n    <td>bitwise AND</td>\r\n  </tr>\r\n  <tr>\r\n    <td>^</td>\r\n    <td>a^b</td>\r\n    <td>bitwise exclusive OR</td>\r\n  </tr>\r\n  <tr>\r\n    <td>|</td>\r\n    <td>a|b</td>\r\n    <td>bitwise inclusive OR</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&&</td>\r\n    <td>a&&b</td>\r\n    <td>logical AND</td>\r\n  </tr>\r\n  <tr>\r\n    <td>||</td>\r\n    <td>a||b</td>\r\n    <td>logical OR</td>\r\n  </tr>\r\n  <tr>\r\n    <td>=</td>\r\n    <td>a=b</td>\r\n    <td>assignment</td>\r\n  </tr>\r\n  <tr>\r\n    <td>,</td>\r\n    <td>(a,b)</td>\r\n    <td>serial evaluation</td>\r\n  </tr>\r\n  <tr>\r\n    <td>.</td>\r\n    <td>A.B</td>\r\n    <td>string concatenation</td>\r\n  </tr>\r\n  <tr>\r\n    <td>eq</td>\r\n    <td>A eq B</td>\r\n    <td>string equality</td>\r\n  </tr>\r\n  <tr>\r\n    <td>ne</td>\r\n    <td>A ne B</td>\r\n    <td>string inequality</td>\r\n  </tr>\r\n</table>\r\n\r\n<h2>Ternary Operator</h2>\r\n\r\n<table border=\"4\" cellpadding=\"5\" cellspacing=\"0\" style=\"width: 100%;\">\r\n  <tr>\r\n    <th>Symbol</th>\r\n    <th>Example</th>\r\n    <th>Explanation</th>\r\n  </tr>\r\n  <tr>\r\n    <td><div>$$\\text{?}:\\text{}$$</div></td>\r\n    <td><div>$$\\text{a ? b : c}$$</div></td>\r\n    <td><div>$$\\text{ternary operation}$$</div></td>\r\n  </tr>\r\n</table>', NULL),
('29', '2', '2', '2', '#Piece-wise Function Plot\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\n#f(x) = 5*x for x<-3 ; f(x) = -5*x for x>3; f(x)=x otherwise\r\nf(x) =(x>3)? -5*x : (x<-3)? 5*x : x\r\npl f(x) w lp', '        <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n<p>Plot a piecewise function where:</p>\r\n\r\n<p>\r\n\\[\r\nf(x) = \r\n\\begin{cases} \r\n5x & \\text{if } x < -3 \\\\ \r\n-5x & \\text{if } x > 3 \\\\ \r\nx & \\text{otherwise}\r\n\\end{cases}\r\n\\]\r\n</p>\r\n\r\n\r\n\r\n', '', NULL),
('30', '2', '2', '3', '#Piecewise function plot\r\nset terminal png size 400, 300\r\nset output \'plot.png\'\r\n#f(x) = 5*x for -3<x<3 ; f(x) = -5*x  otherwise\r\nf(x) =(x>=2)? x**2 :(x>=-1 && x<2)? x: -1 \r\npl f(x) w l lw 2', '        <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n<p>Plot a piecewise function where:</p>\r\n\r\n<p>\r\n\\[\r\nf(x) = \r\n\\begin{cases} \r\nx^2 & \\text{if } x \\geq 2 \\\\ \r\nx & \\text{if } -1 \\leq x < 2 \\\\ \r\n-1 & \\text{otherwise}\r\n\\end{cases}\r\n\\]\r\n</p>', '', NULL),
('31', '2', '2', '4', '# Piecewise function with a hole\r\nset terminal png size 400, 300\r\nset output \'plot.png\'\r\n\r\nf(x) = (x != 0) ? x**2/x : NaN\r\nset xrange [-2:2]\r\nset yrange [-2:2]\r\nplot f(x)', '        <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n<p>Plot a piecewise function where:</p>\r\n\r\n<p>\r\n\\[\r\nf(x) = \r\n\\begin{cases} \r\n\\frac{x^2}{x}  for \\quad x \\neq 0  \\\\ \r\nundefined (NaN) \\quad at \\quad x = 0  \\\\ \r\n\r\n\\end{cases}\r\n\\]\r\n', '', NULL),
('32', '2', '2', '5', '# Piecewise function with or condition\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\n\r\nf(x) = (x < -1 || x > 1) ? 0 : x\r\nset xrange [-2:2]\r\nset yrange [-2:2]\r\nplot f(x) w l lw 2', '        <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n<p>Plot the following piecewise function:</p>\r\n\r\n<p>\r\n\\[\r\nf(x) = \r\n\\begin{cases} \r\n0 & \\text{if } x < -1 \\text{ or } x > 1 \\\\ \r\nx & \\text{if } -1 \\leq x \\leq 1\r\n\\end{cases}\r\n\\]\r\n</p>', '', NULL),
('33', '3', '1', '1', '#Data File\r\n#1	9\r\n#2	10\r\n#3	34\r\n#4	18\r\n#5	20\r\n#6	22\r\n#7	25\r\n#8	31\r\n#9	33\r\n#10	34\r\n#Plot datafile with condition\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\nplot  \'data10.txt\' u 1:($1<7 ? $2 : 1/0)  w lp', '<p>Plot the data points if Values of Column 1 is less than 7 </p>', '\r\n<style>\r\n    table {\r\n        width: 100%;\r\n        \r\n    }\r\n\r\n    th, td {\r\n        word-wrap: break-word;\r\n        white-space: normal;\r\n		text-align: center;\r\n        overflow-wrap: break-word; /* Allows long words to wrap */\r\n    }\r\n\r\n</style>\r\n\r\n\r\n\r\n        <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n    <h2>Unary Operators</h2>\r\n<table border=\"4\" cellpadding=\"5\" cellspacing=\"0\" style=\"width: 100%;\">\r\n    <thead>\r\n        <tr>\r\n            <th>Symbol</th>\r\n            <th>Example</th>\r\n            <th>Explanation</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>-</td>\r\n            <td>\\(-a\\)</td>\r\n            <td>unary minus</td>\r\n        </tr>\r\n        <tr>\r\n            <td>+</td>\r\n            <td>\\(+a\\)</td>\r\n            <td>unary plus (no-operation)</td>\r\n        </tr>\r\n        <tr>\r\n            <td>~</td>\r\n            <td>\\(~a\\)</td>\r\n            <td>one\'s complement</td>\r\n        </tr>\r\n        <tr>\r\n            <td>!</td>\r\n            <td>\\(!a\\)</td>\r\n            <td>logical negation</td>\r\n        </tr>\r\n        <tr>\r\n            <td>!</td>\r\n            <td>\\(a!\\)</td>\r\n            <td>factorial</td>\r\n        </tr>\r\n        <tr>\r\n            <td>$</td>\r\n            <td>\\($3\\)</td>\r\n            <td>call arg/column during \'using\' manipulation</td>\r\n        </tr>\r\n        <tr>\r\n            <td>\\(|\\)</td>\r\n            <td>\\(|A|\\)</td>\r\n            <td>cardinality of array \\( A \\)</td>\r\n        </tr>\r\n    </tbody>\r\n</table >\r\n<h2>Binary Operators</h2>\r\n\r\n<table border=\"4\" cellpadding=\"5\" cellspacing=\"0\" style=\"width: 100%;\">\r\n  <tr>\r\n    <th>Symbol</th>\r\n    <th>Example</th>\r\n    <th>Explanation</th>\r\n  </tr>\r\n  <tr>\r\n    <td>**</td>\r\n    <td>a**b</td>\r\n    <td>exponentiation</td>\r\n  </tr>\r\n  <tr>\r\n    <td>*</td>\r\n    <td>a*b</td>\r\n    <td>multiplication</td>\r\n  </tr>\r\n  <tr>\r\n    <td>/</td>\r\n    <td>a/b</td>\r\n    <td>division</td>\r\n  </tr>\r\n  <tr>\r\n    <td>%</td>\r\n    <td>a%b</td>\r\n    <td>modulo</td>\r\n  </tr>\r\n  <tr>\r\n    <td>+</td>\r\n    <td>a+b</td>\r\n    <td>addition</td>\r\n  </tr>\r\n  <tr>\r\n    <td>-</td>\r\n    <td>a-b</td>\r\n    <td>subtraction</td>\r\n  </tr>\r\n  <tr>\r\n    <td>==</td>\r\n    <td>a==b</td>\r\n    <td>equality</td>\r\n  </tr>\r\n  <tr>\r\n    <td>!=</td>\r\n    <td>a!=b</td>\r\n    <td>inequality</td>\r\n  </tr>\r\n  <tr>\r\n    <td><</td>\r\n    <td>a<b</td>\r\n    <td>less than</td>\r\n  </tr>\r\n  <tr>\r\n    <td><=</td>\r\n    <td>a<=b</td>\r\n    <td>less than or equal to</td>\r\n  </tr>\r\n  <tr>\r\n    <td>></td>\r\n    <td>a>b</td>\r\n    <td>greater than</td>\r\n  </tr>\r\n  <tr>\r\n    <td>>=</td>\r\n    <td>a>=b</td>\r\n    <td>greater than or equal to</td>\r\n  </tr>\r\n  <tr>\r\n    <td><<</td>\r\n    <td>0xff<<1</td>\r\n    <td>left shift unsigned</td>\r\n  </tr>\r\n  <tr>\r\n    <td>>></td>\r\n    <td>0xff>>1</td>\r\n    <td>right shift unsigned</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&</td>\r\n    <td>a&b</td>\r\n    <td>bitwise AND</td>\r\n  </tr>\r\n  <tr>\r\n    <td>^</td>\r\n    <td>a^b</td>\r\n    <td>bitwise exclusive OR</td>\r\n  </tr>\r\n  <tr>\r\n    <td>|</td>\r\n    <td>a|b</td>\r\n    <td>bitwise inclusive OR</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&&</td>\r\n    <td>a&&b</td>\r\n    <td>logical AND</td>\r\n  </tr>\r\n  <tr>\r\n    <td>||</td>\r\n    <td>a||b</td>\r\n    <td>logical OR</td>\r\n  </tr>\r\n  <tr>\r\n    <td>=</td>\r\n    <td>a=b</td>\r\n    <td>assignment</td>\r\n  </tr>\r\n  <tr>\r\n    <td>,</td>\r\n    <td>(a,b)</td>\r\n    <td>serial evaluation</td>\r\n  </tr>\r\n  <tr>\r\n    <td>.</td>\r\n    <td>A.B</td>\r\n    <td>string concatenation</td>\r\n  </tr>\r\n  <tr>\r\n    <td>eq</td>\r\n    <td>A eq B</td>\r\n    <td>string equality</td>\r\n  </tr>\r\n  <tr>\r\n    <td>ne</td>\r\n    <td>A ne B</td>\r\n    <td>string inequality</td>\r\n  </tr>\r\n</table>\r\n\r\n<h2>Ternary Operator</h2>\r\n\r\n<table border=\"4\" cellpadding=\"5\" cellspacing=\"0\" style=\"width: 100%;\">\r\n  <tr>\r\n    <th>Symbol</th>\r\n    <th>Example</th>\r\n    <th>Explanation</th>\r\n  </tr>\r\n  <tr>\r\n    <td><div>$$\\text{?}:\\text{}$$</div></td>\r\n    <td><div>$$\\text{a ? b : c}$$</div></td>\r\n    <td><div>$$\\text{ternary operation}$$</div></td>\r\n  </tr>\r\n</table>', NULL),
('34', '3', '1', '2', '#data11.txt\r\n#1	2	4\r\n#2	4	4\r\n#3	6	9\r\n#4	8	16\r\n#5	10	25\r\n#6	12	36\r\n#7	14	49\r\n#8	16	64\r\n#9	18	81\r\n#10	20	100\r\n\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\n\r\n#plot data col1:col2 if 19<col3<65\r\nplot  \'data11.txt\' u 1:($3>19 && $3<65 ? $2 : 1/0)  w lp lw 2', 'plot col1:col2 if col3 is greater than 19 and less than 65', '', NULL),
('35', '3', '1', '3', '#data11.txt\r\n#1	2	4\r\n#2	4	4\r\n#3	6	9\r\n#4	8	16\r\n#5	10	25\r\n#6	12	36\r\n#7	14	49\r\n#8	16	64\r\n#9	18	81\r\n#10	20	100\r\n\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\n\r\n#plot data col1:col2 if (19<col3 or col3>65)\r\nplot  \'data11.txt\' u 1:($3<19 || $3>63  ? $2 : 1/0)  w lp ps 5', 'plot data col1:col2 if 19 col3 is less than 19 or greater than 65', '', NULL),
('36', '3', '1', '4', '#data11.txt\r\n#1	2	4\r\n#2	4	4\r\n#3	6	9\r\n#4	8	16\r\n#5	10	25\r\n#6	12	36\r\n#7	14	49\r\n#8	16	64\r\n#9	18	81\r\n#10	20	100\r\n\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\n\r\n#plot data col1:col3 if col2>6 and (col3<37 or col3>80)\r\nplot  \'data11.txt\' u 1:($2 > 6 && \\\r\n	($3 < 37 || $3 > 80) ? $3 : 1/0)  \\\r\n	w lp ps 5', 'plot col1:col3 if col2 is less that 6 and (col3 is less than 37 or col3 is greater than 80)', '', NULL),
('37', '4', '1', '1', '#data13.txt\r\n#1	9\r\n#2	20\r\n#3	32\r\n#4	39\r\n#5	51\r\n#6	58\r\n#7	73\r\n#8	84\r\n#9	90\r\n#10	98\r\n\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\n\r\n#Fit data with the following function\r\nf(x) = a*x + b #Fitting Function\r\nfit f(x) \'data13.txt\' via a, b\r\npl \'data13.txt\' w p ps 3, f(x) w l', 'Fit data with the function a*x + b', '', NULL),
('38', '4', '1', '2', '#data12.txt\r\n#1	1	1\r\n#2	4	1\r\n#3	9	1\r\n#4	16	10\r\n#5	25	1\r\n#6	36	1\r\n#7	49	1\r\n#8	64	1\r\n#9	80	1\r\n#10	97	1\r\n\r\nset terminal png size 600, 400\r\nset output \'plot.png\'\r\n\r\n#Fit data with the following function\r\nf(x) = a*x**2 #Fitting Function\r\nfit f(x) \'data12.txt\' via a\r\npl \'data12.txt\' w p, f(x) w l', 'Fit data with the function a*x**2', '', NULL),
