('47', '2', '2', '6', 'set terminal png\r\nset output \'plot.png\'\r\n\r\nset xrange [-2:3]\r\nset yrange [-5:5]\r\nset xtics 1\r\nset ytics 2\r\nset title \"Piece-wise continuous functions\"\r\n\r\nf(x) = (x >= 2) ? (1.45 * x**3 - 6 * sqrt(x)) : 1/0\r\ng(x) = (x >= -1 && x < 2) ? sin(x)**2 : 1/0\r\nh(x) = (x < -1) ? abs(x) * exp(x) : 1/0\r\n\r\nplot f(x) title \"f(x) = 1.45x^3 - 6âˆšx, x â‰¥ 2\" lw 2 lc rgb \"red\", \\\r\n     g(x) title \"g(x) = sin^2(x), -1 â‰¤ x < 2\" lw 2 lc rgb \"blue\", \\\r\n     h(x) title \"h(x) = |x| e^x, x < -1\" lw 2 lc rgb \"green\"', '        <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n    <p>Three functions are defined in the given range as follows:</p>\r\n\r\n    <div class=\"equation\">\r\n        \\( f(x) = 1.45x^3 - 6\\sqrt{x}, \\quad x \\geq 2 \\)\r\n    </div>\r\n    <div class=\"equation\">\r\n        \\( g(x) = \\sin^2(x), \\quad -1 \\leq x < 2 \\)\r\n    </div>\r\n    <div class=\"equation\">\r\n        \\( h(x) = |x| e^x, \\quad x < -1 \\)\r\n    </div>\r\n\r\n    <p>\r\n        Plot the three functions using GNUPLOT.\r\n    </p>', '', NULL),
('48', '2', '2', '7', 'set terminal png\r\nset output \'plot.png\'\r\nset xrange [0:pi]  # or you can use set xrange [0:*]\r\nset yrange [-2:2]\r\nset xlabel \"x-values\"\r\nset ylabel \"y-values\"\r\nset title \"Function plots\"\r\nset samples 1000\r\n\r\n# Define the functions\r\nf1(x) = sin(sqrt(x))**2\r\nf2(x) = exp(-x/2)*cos(2*pi*x)\r\nf3(x) = 12.34*x**(5.0/3.0)\r\n\r\n# Plot the functions with different line styles and widths\r\nplot f1(x) title \"f1(x)\" lw 2 lc rgb \"red\", \\\r\n     f2(x) title \"f2(x)\" lw 3 lc rgb \"blue\", \\\r\n     f3(x) title \"f3(x)\" lw 4 lc rgb \"green\"', '    <script Â   id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script> Â  \r\n\r\n<p>Plot the following functions for \\(0 \\le x \\le \\pi\\) on the same graph using GNUPLOT. Set 1000 samples. \r\nMark each curve with different line style and line widths. </p>\r\n\r\n<p>\\(f_1(x) = \\sin^2(\\sqrt{x})\\)</p>\r\n<p>\\(f_2(x) = e^{-x/2} \\cos(2\\pi x)\\)</p>\r\n<p>\\(f_3(x) = 12.34x^{5/3}\\)</p>', '', NULL),
('49', '5', '1', '6', 'set terminal png\r\nset output \"polar_plot.png\"\r\nset polar\r\n\r\nset rrange [-3:3]\r\n\r\nset title \"Polar Function Plot\"\r\n\r\n# Define the functions\r\nr1(t) = t**2 * sin(t/pi)\r\nr2(t) = 3.75*exp(-t/2.39)\r\n\r\nplot r1(t) title \"r1(t)\" lw 2 lc rgb \"red\" , \\\r\n     r2(t) title \"r2(t)\" lw 3 lc rgb \"blue\"', '    <script Â   id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script> Â  \r\n\r\n<p>Plot the following polar equations in GNUPLOT:</p>\r\n\r\n<p>\\(r(\\theta) = \\theta^2 \\sin(\\theta/\\pi)\\)</p>\r\n<p>\\(r(\\theta) = 3.75e^{-\\theta/2.39}\\)</p>\r\n\r\n<p>Consider \\(\\theta\\) range to be \\(-\\pi\\) to \\(\\pi\\) and the radial \\(r(\\theta)\\) range to be \\(-3 < r < 3\\). Set different line types for the two functions. Put the title \"Polar function plot\". Save the plot in a suitable format.</p>', '', NULL);
INSERT INTO `latex` (`id`, `menu_id`, `submenu_id`, `program_id`, `content`, `algo`, `explanation`) VALUES
('1', '1', '1', '1', '\\documentclass{article}\r\n\r\n\\title{My First LaTeX Document}\r\n\\author{John Doe}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\section{Introduction}\r\nThis is a simple introduction section. LaTeX is used for creating professional-looking documents.\r\n\r\n\\section{Main Content}\r\nHere is the main content. You can add equations, like this:\r\n\\[\r\nE = mc^2\r\n\\]\r\n\r\n\\section{Conclusion}\r\nThis is the conclusion section.\r\n\r\n\\end{document}', NULL, NULL),
('2', '1', '1', '2', '\\documentclass[12pt]{report}\r\n\\usepackage{amsmath}\r\n\\usepackage{graphicx}\r\n\r\n\\title{A Simple Report Example}\r\n\\author{Your Name}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\begin{abstract}\r\nThis is a simple report abstract. It provides a brief summary of the report\'s content.\r\n\\end{abstract}\r\n\r\n\\tableofcontents\r\n\r\n\\chapter{Introduction}\r\nThis is the introduction chapter of a report. Reports often have more structure and detailed sections.\r\n\r\n\\chapter{Literature Review}\r\nIn this chapter, you discuss previous research and literature on your topic.\r\n\r\n\\chapter{Methodology}\r\nHere you describe the methods you used to conduct your research.\r\n\r\n\\chapter{Results}\r\nPresent the results of your study or research here.\r\n\r\n\\chapter{Conclusion}\r\nSummarize your findings and discuss their implications.\r\n\r\n\\appendix\r\n\\chapter{Appendix A}\r\nInclude any supplementary material or data here.\r\n\r\n\\end{document}\r\n', NULL, NULL),
('3', '1', '1', '3', '\\documentclass[12pt]{letter}\r\n\\usepackage{graphicx}\r\n\r\n\\signature{Your Name}\r\n\r\n\\begin{document}\r\n\r\n\\begin{letter}{Recipient Name \\\\ Address Line 1 \\\\ Address Line 2}\r\n\r\n\\opening{Dear Recipient Name,}\r\n\r\nThis is a simple letter written in LaTeX. You can use this template for formal or informal correspondence.\r\n\r\n\\closing{Sincerely,}\r\n\r\n\\ps{P.S. You can add a postscript here.}\r\n\r\n\\encl{Attachment (if any)}\r\n\r\n\\end{letter}\r\n\r\n\\end{document}\r\n', NULL, NULL),
('4', '1', '1', '4', '\\documentclass[12pt]{article}\r\n\\usepackage{geometry}\r\n\\geometry{a4paper, margin=1in}\r\n\\usepackage{enumitem}\r\n\r\n\\title{Your Name}\r\n\\date{}\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\\thispagestyle{empty}\r\n\r\n\\section*{Contact Information}\r\n\\begin{itemize}[leftmargin=0pt, label={}]\r\n    \\item Email: your.email@example.com\r\n    \\item Phone: +123 456 7890\r\n    \\item Address: 123 Street Name, City, Country\r\n\\end{itemize}\r\n\r\n\\section*{Education}\r\n\\begin{itemize}\r\n    \\item \\textbf{Degree, Major} \\\\\r\n    University Name, Graduation Year\r\n\\end{itemize}\r\n\r\n\\section*{Experience}\r\n\\begin{itemize}\r\n    \\item \\textbf{Job Title} \\\\\r\n    Company Name, Duration \\\\\r\n    Brief description of responsibilities and achievements.\r\n\\end{itemize}\r\n\r\n\\section*{Skills}\r\n\\begin{itemize}\r\n    \\item Skill 1\r\n    \\item Skill 2\r\n    \\item Skill 3\r\n\\end{itemize}\r\n\r\n\\section*{References}\r\nAvailable upon request.\r\n\r\n\\end{document}\r\n', NULL, NULL),
('5', '4', '1', '1', '\\documentclass{article}\r\n\\usepackage{enumitem}\r\n\r\n\\begin {document}\r\n\\begin{itemize}\r\n\\item Physics\r\n\\item Chemistry\r\n\\item Biology\r\n\\item  Maths\r\n\\end{itemize}\r\n\r\n\\begin{itemize}\r\n\\item [+] Physics\r\n\\item [\\#] Chemistry\r\n\\item[-]Biology\r\n\\item[*] Maths\r\n\\end{itemize}\r\n\r\n\\end{document}', NULL, NULL),
('6', '4', '2', '1', '\\documentclass{article}\r\n\\usepackage{enumitem}\r\n\r\n\\begin {document}\r\n\\begin{enumerate}\r\n  \\item Python\r\n  \\item Latex \r\n  \\item Arduino\r\n\\end{enumerate}\r\n\r\n\\begin{enumerate}[label=(\\arabic*)]\r\n   \\item Arts\r\n   \\item Science\r\n\\end{enumerate}\r\n\\begin{enumerate}[label=(\\roman*)]\r\n    \\item Maths\r\n    \\item Physics\r\n \\end{enumerate}\r\n\\begin{enumerate}[label=(\\Roman*)]\r\n    \\item First year\r\n    \\item Second year\r\n\\end{enumerate}\r\n\\begin{enumerate}[label=(\\alph*)]\r\n    \\item Optics\r\n    \\item Electrodynamics\r\n\\end{enumerate} \r\n\\end{document}', NULL, NULL),
('7', '4', '3', '1', '\\documentclass{article}\r\n\\usepackage{enumitem}\r\n\r\n\\begin {document}\r\n\\begin{description}\r\n   \\item This is an entry \\textit{without} a label.\r\n   \\item[with label] A short one-line description.\r\n   \\item[long description] A much longer description can be given here according to the need of the user.  \r\n\\end{description}\r\n\\end{document}', NULL, NULL),
('8', '5', '1', '1', '\\documentclass{article}\r\n\\begin {document}\r\n\\section{Font emphasize}\r\n\r\nbold:	\\textbf{Einstein}	\\\\\r\nupright	:\\textup{Nikola Tesla}\\\\	\r\nitalic:	\\textit{C.V. Raman}	\\\\\r\nBold Italic: \\textbf{\\emph{bold italic text}} \\\\\r\nUnderline: \\underline{underline text} \\\\ \r\nSmall caps: \\textsc{small caps text} \\\\ \r\nMonospaced: \\texttt{monospaced text} \\\\ \r\nSans serif: \\textsf{sans serif text} \\\\ \r\nSuperscript: \\textsuperscript{superscript} \\\\ \r\nslanted	:\\textsl{Maxwell}	\\\\\r\nsmall capitals:	\\textsc{Newton}\\\\\r\nmedium font:  \\textmd{Dirac}\\\\\r\ntypewriter text: \\texttt{J.J. Thomson}\r\n\r\n\\section{Font family}\r\n\\textrm{Roman family}\\\\\r\n\\textsf{Sans serif}\\\\\r\n\\sffamily{another way to change font family to sans serif}\\\\\r\n\\textnormal{normal document font}\r\n\r\n\\end{document}', NULL, NULL),
('9', '5', '2', '1', '\\documentclass{article}\r\n\\begin {document}\r\n\\tiny	Physics\\\\\r\n\\scriptsize	Physics\\\\\r\n\\footnotesize	Physics\\\\\r\n\\small	Physics\\\\\r\n\\normalsize	Physics\\\\\r\n\\large	Physics\\\\\r\n\\Large	Physics\\\\\r\n\\LARGE	Physics\\\\\r\n\\huge	Physics\\\\\r\n\\Huge	Physics\\\\\r\n\\end{document}', NULL, NULL),
('10', '6', '1', '1', '\\documentclass{article}\r\n\\usepackage[utf8]{inputenc}\r\n\r\n\\begin{document}\r\n	\\section{Special character}\r\n	\r\n	\\subsection{Upper case Greek letters}\r\n	\\[\r\n	\\Gamma \\\\\r\n	\\Delta \\\\\r\n	\\Lambda \\\\\r\n	\\Phi \\\\\r\n	\\Pi \\\\\r\n	\\Psi \\\\\r\n	\\Sigma \\\\\r\n	\\Theta \\\\\r\n	\\Upsilon \\\\\r\n	\\Xi \\\\\r\n	\\Omega\r\n	\\]\r\n	\r\n	\\subsection{Lower case Greek letters}\r\n	\\[\r\n	\\alpha \\\\\r\n	\\beta \\\\\r\n	\\gamma \\\\\r\n	\\delta \\\\\r\n	\\epsilon \\\\\r\n	\\zeta \\\\\r\n	\\eta \\\\\r\n	\\theta \\\\\r\n	\\iota \\\\\r\n	\\kappa \\\\\r\n	\\lambda \\\\\r\n	\\mu \\\\\r\n	\\nu \\\\\r\n	\\xi \\\\\r\n	\\pi \\\\\r\n	\\rho \\\\\r\n	\\sigma \\\\\r\n	\\tau \\\\\r\n	\\upsilon \\\\\r\n	\\phi \\\\\r\n	\\chi \\\\\r\n	\\psi \\\\\r\n	\\omega\r\n	\\]\r\n	\r\n	\\subsection{Symbols}\r\n	\\[\r\n	\\# \\\\\r\n	\\angle \\\\\r\n	\\bot \\\\\r\n	\\clubsuit \\\\\r\n	\\diamondsuit \\\\\r\n	\\emptyset \\\\\r\n	\\exists \\\\\r\n	\\flat \\\\\r\n	\\forall \\\\\r\n	\\heartsuit \\\\\r\n	\\infty \\\\\r\n	\\nabla \\\\\r\n	\\natural \\\\\r\n	\\prime \\\\\r\n	\\S \\\\\r\n	\\sharp \\\\\r\n	\\spadesuit \\\\\r\n	\\surd \\\\\r\n	\\top \\\\\r\n	\\triangle\r\n	\\]\r\n\\end{document}\r\n', NULL, NULL),
('11', '2', '2', '1', '\\documentclass{article}\r\n\r\n\\title{Physics Class Report}\r\n\\author{Your Name}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\section{Introduction}\r\nIn this report, we will discuss basic concepts in physics, including Newton\'s Laws of Motion and energy conservation principles.\r\n\r\n\\section{Newton\'s First Law}\r\nNewton\'s First Law states that an object at rest stays at rest and an object in motion stays in motion unless acted upon by an external force.\r\n\r\n\\section{Newton\'s Second Law}\r\nAccording to Newton\'s Second Law, the force on an object is equal to its mass multiplied by its acceleration.\r\n\r\n\\section{Conclusion}\r\nUnderstanding these basic laws is fundamental to studying more complex topics in physics.\r\n\r\n\\end{document}', NULL, NULL),
('12', '2', '2', '2', '\\documentclass{article}\r\n\r\n\\title{Class Report on Energy and Work}\r\n\\author{Your Name}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\section{Introduction}\r\nThis report covers the concepts of work and energy in classical mechanics.\r\n\r\n\\section{Work}\r\nWork is defined as the force applied to an object multiplied by the distance over which it is applied in the direction of the force.\r\n\r\n\\section{Kinetic Energy}\r\nKinetic energy is the energy an object possesses due to its motion, which is given by the formula: $KE = \\frac{1}{2} mv^2$, where $m$ is mass and $v$ is velocity.\r\n\r\n\\section{Conclusion}\r\nThe relationship between work and energy is essential in solving real-world physics problems.\r\n\r\n\\end{document}', NULL, NULL),
('13', '2', '2', '3', '\\documentclass{article}\r\n\r\n\\title{Physics Report on Gravity}\r\n\\author{Your Name}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\section{Introduction}\r\nGravity is a fundamental force of nature, responsible for the attraction between masses.\r\n\r\n\\section{Gravitational Force}\r\nNewtonâ€™s Law of Universal Gravitation states that the force of gravity between two objects is proportional to the product of their masses and inversely proportional to the square of the distance between them.\r\n\r\n\\section{Impact of Gravity on Earth}\r\nOn Earth, gravity gives weight to objects and causes them to fall when dropped.\r\n\r\n\\section{Conclusion}\r\nUnderstanding gravity is crucial for studying motion, astronomy, and general physics.\r\n\r\n\\end{document}', NULL, NULL),
('14', '2', '2', '4', '\\documentclass{article}\r\n\r\n\\title{Class Report on Electromagnetism}\r\n\\author{Your Name}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\section{Introduction}\r\nElectromagnetism is one of the four fundamental forces and describes the interaction between electrically charged particles.\r\n\r\n\\section{Electric Fields}\r\nAn electric field is a region of space around an electrically charged object where other charged objects experience a force.\r\n\r\n\\section{Magnetic Fields}\r\nA magnetic field is generated when electric charges move, as seen in electromagnets and permanent magnets.\r\n\r\n\\section{Conclusion}\r\nElectromagnetism plays a crucial role in modern physics and technology, from electric motors to radio waves.\r\n\r\n\\end{document}', NULL, NULL),
('15', '2', '1', '1', '\\documentclass{report}\r\n\r\n\\title{Physics Report on Classical Mechanics}\r\n\\author{Your Name}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\chapter{Introduction}\r\nThis report explores fundamental concepts in classical mechanics, including Newton\'s Laws of Motion and energy principles. Classical mechanics is the study of how forces affect the motion of bodies.\r\n\r\n\\chapter{Newton\'s Laws of Motion}\r\n\r\n\\section{First Law}\r\nNewton\'s First Law, also known as the law of inertia, states that an object at rest remains at rest, and an object in motion continues in motion with constant velocity unless acted upon by an external force.\r\n\r\n\\section{Second Law}\r\nThe Second Law defines the relationship between force, mass, and acceleration. It can be summarized by the equation:\r\n\\[ F = ma \\]\r\nwhere $F$ is the force applied to an object, $m$ is its mass, and $a$ is its acceleration.\r\n\r\n\\section{Third Law}\r\nNewtonâ€™s Third Law states that for every action, there is an equal and opposite reaction. This principle explains the forces between two interacting bodies.\r\n\r\n\\chapter{Energy and Work}\r\n\r\n\\section{Work}\r\nWork is defined as the force applied to an object multiplied by the distance it moves in the direction of the force.\r\n\r\n\\section{Kinetic Energy}\r\nKinetic energy is the energy of motion, calculated using the formula $KE = \\frac{1}{2} mv^2$, where $m$ is mass and $v$ is velocity.\r\n\r\n\\section{Potential Energy}\r\nPotential energy is stored energy due to an object\'s position or configuration, most commonly due to gravity in classical mechanics.\r\n\r\n\\chapter{Conclusion}\r\nNewtonâ€™s Laws and the concepts of work and energy form the foundation of classical mechanics. These principles are essential for understanding motion, forces, and energy conservation in physical systems.\r\n\r\n\\end{document}', NULL, NULL),
('16', '2', '1', '2', '\\documentclass{report}\r\n\r\n\\title{Physics Report on Gravitational Theory}\r\n\\author{Your Name}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\chapter{Introduction}\r\nThis report discusses the principles of gravitational theory, focusing on Newton\'s Law of Universal Gravitation and its impact on celestial mechanics.\r\n\r\n\\chapter{Newton\'s Law of Universal Gravitation}\r\n\r\n\\section{Gravitational Force}\r\nNewtonâ€™s Law of Universal Gravitation states that every point mass attracts every other point mass with a force that is directly proportional to the product of their masses and inversely proportional to the square of the distance between them.\r\n\r\n\r\n\\chapter{Applications in Celestial Mechanics}\r\n\r\n\\section{Orbital Motion}\r\nGravitational theory is essential for understanding orbital motion. Planets follow elliptical orbits due to the gravitational pull of the Sun, as described by Kepler\'s laws.\r\n\r\n\\section{Tidal Forces}\r\nTides on Earth are caused by the gravitational pull of the Moon. The force of gravity between the Earth and the Moon causes water to bulge, leading to high and low tides.\r\n\r\n\\chapter{Conclusion}\r\nGravitational theory is fundamental to our understanding of the universe, governing the motion of planets, stars, and galaxies.\r\n\r\n\\end{document}', NULL, NULL),
('17', '2', '1', '3', '\\documentclass{report}\r\n\r\n\\title{Physics Report on Electromagnetism}\r\n\\author{Your Name}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\n\\chapter{Introduction}\r\nThis report explores the concepts of electromagnetism, one of the four fundamental forces, which describes the interaction between electric charges and magnetic fields.\r\n\r\n\\chapter{Electric Fields}\r\n\r\n\\section{Definition}\r\nAn electric field is a region of space around a charged object where other charged objects experience a force. The strength of the field is proportional to the magnitude of the charge and inversely proportional to the square of the distance from the charge.\r\n\r\n\\section{Electric Field Lines}\r\nElectric field lines are a visual representation of the strength and direction of an electric field. The lines point away from positive charges and toward negative charges.\r\n\r\n\\chapter{Magnetic Fields}\r\n\r\n\\section{Definition}\r\nA magnetic field is generated by moving electric charges. This field exerts a force on other moving charges, which is the principle behind electromagnets and motors.\r\n\r\n\\section{Magnetic Field Around a Current-Carrying Wire}\r\nWhen an electric current flows through a wire, it generates a circular magnetic field around the wire. This principle is used in electromagnets, where electric currents produce strong magnetic fields.\r\n\r\n\\chapter{Conclusion}\r\nElectromagnetism is a crucial area of physics that underlies many modern technologies, from electric motors to wireless communication.\r\n\r\n\\end{document}', NULL, NULL),
('18', '2', '3', '1', '\\documentclass{book}\r\n\r\n\\begin{document}\r\n	\r\n	\\chapter{Newton\'s Laws of Motion}\r\n	\r\n	\\section{Introduction}\r\n	\r\n	Newton\'s Laws of Motion are three fundamental laws that describe the relationship between the motion of an object and the forces acting upon it.\r\n	\r\n	\\section{First Law: Law of Inertia}\r\n	\r\n	The first law states that an object at rest will remain at rest, and an object in motion will continue in motion with a constant velocity, unless acted upon by a net external force.\r\n	\r\n	\\section{Second Law: Force and Acceleration}\r\n	\r\n	The second law explains how the velocity of an object changes when it is subjected to an external force. This law is the basis for the equation of motion.\r\n	\r\n	\\section{Third Law: Action and Reaction}\r\n	\r\n	The third law states that for every action, there is an equal and opposite reaction. It highlights the interaction between two objects in contact.\r\n	\r\n\\end{document}', NULL, NULL),
('19', '2', '3', '2', '\\documentclass{book}\r\n\r\n\\begin{document}\r\n\r\n\\chapter{The Laws of Thermodynamics}\r\n\r\n\\section{Introduction}\r\n\r\nThe laws of thermodynamics are a set of principles that describe the behavior of energy in systems, especially as it pertains to heat and work.\r\n\r\n\\section{Zeroth Law of Thermodynamics}\r\n\r\nThe Zeroth Law states that if two systems are each in thermal equilibrium with a third system, then they are in thermal equilibrium with each other.\r\n\r\n\\section{First Law of Thermodynamics}\r\n\r\nThe First Law states that energy cannot be created or destroyed, only transformed from one form to another. This law is a version of the law of conservation of energy.\r\n\r\n\\section{Second Law of Thermodynamics}\r\n\r\nThe Second Law states that the total entropy of an isolated system can never decrease over time. This law explains the direction of spontaneous processes.\r\n\r\n\\end{document}', NULL, NULL),
('20', '2', '3', '3', '\\documentclass{book}\r\n\r\n\\begin{document}\r\n	\r\n	\\title{Introduction to Classical Mechanics}\r\n	\\author{A Chatterjee}\r\n	\\date{\\today}\r\n	\\maketitle\r\n	\r\n	\\tableofcontents\r\n	\r\n	\\chapter{Kinematics}\r\n	\r\n	\\section{Introduction}\r\n	\r\n	Kinematics is the branch of mechanics that deals with the motion of objects without considering the forces that cause the motion. It focuses on parameters like displacement, velocity, and acceleration.\r\n	\r\n	\\newpage\r\n	\r\n	\\section{Displacement}\r\n	\r\n	Displacement refers to the change in position of an object. It is a vector quantity, meaning it has both magnitude and direction.\r\n	\r\n	\\section{Velocity}\r\n	\r\n	Velocity is the rate of change of displacement with respect to time. It is also a vector quantity, which means it considers both speed and direction.\r\n	\r\n	\\newpage\r\n	\r\n	\\section{Acceleration}\r\n	\r\n	Acceleration is the rate of change of velocity with respect to time. It describes how an objectâ€™s velocity changes over time.\r\n	\r\n	\\chapter{Dynamics}\r\n	\r\n	\\section{Introduction}\r\n	\r\n	Dynamics is the study of forces and their effects on motion. It explains why objects move the way they do, relating to Newton\'s Laws of Motion.\r\n	\r\n	\\newpage\r\n	\r\n	\\section{Force}\r\n	\r\n	Force is any interaction that, when unopposed, changes the motion of an object. It can cause an object to accelerate, decelerate, or change direction.\r\n	\r\n	\\section{Momentum}\r\n	\r\n	Momentum is the product of an object\'s mass and velocity. It is a vector quantity and is important in understanding collisions and other interactions.\r\n	\r\n\\end{document}', NULL, NULL),
('21', '2', '3', '4', '\\documentclass{book}\r\n\r\n\\begin{document}\r\n	\r\n	\\title{Fundamentals of Electromagnetism}\r\n	\\author{Jane Smith}\r\n	\\date{\\today}\r\n	\\maketitle\r\n	\r\n	\\tableofcontents\r\n	\r\n	\\chapter{Electric Fields}\r\n	\r\n	\\section{Introduction}\r\n	\r\n	An electric field is a region of space around an electrically charged particle or object where an electric force is exerted on other charged particles or objects.\r\n	\r\n	\\newpage\r\n	\r\n	\\section{Coulomb\'s Law}\r\n	\r\n	Coulomb\'s law quantifies the electric force between two charged particles. The force is directly proportional to the product of the charges and inversely proportional to the square of the distance between them.\r\n	\r\n	\\section{Electric Potential}\r\n	\r\n	Electric potential is the work needed to move a unit charge from a reference point to a specific point inside the field without producing acceleration.\r\n	\r\n	\\newpage\r\n	\r\n	\\chapter{Magnetic Fields}\r\n	\r\n	\\section{Introduction}\r\n	\r\n	A magnetic field is a vector field that describes the magnetic influence on moving electric charges, electric currents, and magnetic materials.\r\n	\r\n	\\newpage\r\n	\r\n	\\section{Magnetic Force}\r\n	\r\n	The magnetic force is the force experienced by a moving charge in a magnetic field. This force is perpendicular to both the velocity of the charge and the magnetic field.\r\n	\r\n	\\section{Electromagnetic Induction}\r\n	\r\n	Electromagnetic induction is the process of generating electric current from a changing magnetic field. This principle is used in the operation of transformers and electric generators.\r\n	\r\n\\end{document}', NULL, NULL),
('22', '3', '1', '1', '\\documentclass[twocolumn]{book}\r\n\r\n\\title{Two-Column Layout}\r\n\\author{Physics Content}\r\n\\date{\\today}\r\n\r\n\\begin{document}\r\n	\r\n	\\maketitle\r\n	\r\n	\\chapter{Optics}\r\n	\r\n	\\section{Introduction}\r\n	\r\n	Optics is the study of light and its interaction with matter. Light can be described as both a wave and a particle.\r\n	\r\n	\\section{Reflection}\r\n	\r\n	Reflection occurs when light bounces off a surface, with the angle of incidence equaling the angle of reflection.\r\n	\r\n	\\section{Refraction}\r\n	\r\n	Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refraction is the bending of light as it passes from one medium to another with a different refractive index. Refract