('46', '6', '2', '13', '\\documentclass{article}\r\n\\usepackage{amsmath}\r\n\r\n\\title{Wave Equation}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\r\nThe wave equation is:\r\n\r\n\\[\r\n\\frac{\\partial^2 u}{\\partial t^2} = c^2 \\left( \\frac{\\partial^2 u}{\\partial x^2} + \\frac{\\partial^2 u}{\\partial y^2} \\right)\r\n\\]\r\n\r\nwhere \\(u\\) is the wave function and \\(c\\) is the speed of the wave.\r\n\r\n\\end{document}', NULL, NULL),
('47', '6', '3', '1', '\\documentclass{article}\r\n\\usepackage{amsmath}\r\n\\usepackage{amssymb}\r\n\\usepackage{amsfonts}\r\n\\usepackage{bm}\r\n\r\n\\title{Physics Equations}\r\n\\author{}\r\n\\date{}\r\n\r\n\\begin{document}\r\n	\r\n	\\maketitle\r\n	\r\n	\\section*{Algebraic Equations}\r\n	\r\n	1. Newton\'s Second Law of Motion:\r\n	\\begin{equation}\r\n		F = ma\r\n	\\end{equation}\r\n	\r\n	2. Gravitational Force:\r\n	\\begin{equation}\r\n		F = G \\frac{m_1 m_2}{r^2}\r\n	\\end{equation}\r\n	\r\n	3. Kinetic Energy:\r\n	\\begin{equation}\r\n		KE = \\frac{1}{2} mv^2\r\n	\\end{equation}\r\n	\r\n	4. Potential Energy (Gravitational):\r\n	\\begin{equation}\r\n		PE = mgh\r\n	\\end{equation}\r\n	\r\n	5. Work Done by a Force:\r\n	\\begin{equation}\r\n		W = Fd \\cos \\theta\r\n	\\end{equation}\r\n	\r\n	6. Power:\r\n	\\begin{equation}\r\n		P = \\frac{W}{t}\r\n	\\end{equation}\r\n	\r\n	7. Ohm\'s Law:\r\n	\\begin{equation}\r\n		V = IR\r\n	\\end{equation}\r\n	\r\n	8. Coulomb\'s Law:\r\n	\\begin{equation}\r\n		F = k_e \\frac{q_1 q_2}{r^2}\r\n	\\end{equation}\r\n	\r\n	9. Hooke\'s Law:\r\n	\\begin{equation}\r\n		F = -kx\r\n	\\end{equation}\r\n	\r\n	10. Momentum:\r\n	\\begin{equation}\r\n		p = mv\r\n	\\end{equation}\r\n	\r\n	\\section*{Vector Equations}\r\n	\r\n	11. Force as a Vector:\r\n	\\begin{equation}\r\n		\\bm{F} = m \\bm{a}\r\n	\\end{equation}\r\n	\r\n	12. Velocity Vector:\r\n	\\begin{equation}\r\n		\\bm{v} = \\frac{d\\bm{r}}{dt}\r\n	\\end{equation}\r\n	\r\n	13. Acceleration Vector:\r\n	\\begin{equation}\r\n		\\bm{a} = \\frac{d\\bm{v}}{dt}\r\n	\\end{equation}\r\n	\r\n	14. Dot Product of Vectors:\r\n	\\begin{equation}\r\n		\\bm{A} \\cdot \\bm{B} = |\\bm{A}| |\\bm{B}| \\cos \\theta\r\n	\\end{equation}\r\n	\r\n	15. Cross Product of Vectors:\r\n	\\begin{equation}\r\n		\\bm{A} \\times \\bm{B} = |\\bm{A}| |\\bm{B}| \\sin \\theta \\hat{n}\r\n	\\end{equation}\r\n	\r\n	16. Electric Field:\r\n	\\begin{equation}\r\n		\\bm{E} = \\frac{1}{4 \\pi \\epsilon_0} \\frac{q}{r^2} \\hat{r}\r\n	\\end{equation}\r\n	\r\n	17. Lorentz Force:\r\n	\\begin{equation}\r\n		\\bm{F} = q \\left( \\bm{E} + \\bm{v} \\times \\bm{B} \\right)\r\n	\\end{equation}\r\n	\r\n	18. Magnetic Field of a Moving Charge:\r\n	\\begin{equation}\r\n		\\bm{B} = \\frac{\\mu_0}{4\\pi} \\frac{q \\bm{v} \\times \\hat{r}}{r^2}\r\n	\\end{equation}\r\n	\r\n	19. Vector Form of Newtonâ€™s Second Law:\r\n	\\begin{equation}\r\n		\\sum \\bm{F} = m \\bm{a}\r\n	\\end{equation}\r\n	\r\n	20. Angular Momentum:\r\n	\\begin{equation}\r\n		\\bm{L} = \\bm{r} \\times \\bm{p}\r\n	\\end{equation}\r\n	\r\n	\\section*{Thermodynamics and Statistical Physics}\r\n	\r\n	21. First Law of Thermodynamics:\r\n	\\begin{equation}\r\n		\\Delta U = Q - W\r\n	\\end{equation}\r\n	\r\n	22. Ideal Gas Law:\r\n	\\begin{equation}\r\n		PV = nRT\r\n	\\end{equation}\r\n	\r\n	23. Entropy Change:\r\n	\\begin{equation}\r\n		\\Delta S = \\frac{\\Delta Q}{T}\r\n	\\end{equation}\r\n	\r\n	24. Heat Transfer (Conduction):\r\n	\\begin{equation}\r\n		Q = -k A \\frac{dT}{dx}\r\n	\\end{equation}\r\n	\r\n	25. Stefan-Boltzmann Law:\r\n	\\begin{equation}\r\n		P = \\sigma A T^4\r\n	\\end{equation}\r\n	\r\n	26. Boltzmann Distribution:\r\n	\\begin{equation}\r\n		f(E) = \\frac{1}{Z} e^{-E/k_B T}\r\n	\\end{equation}\r\n	\r\n	27. Carnot Efficiency:\r\n	\\begin{equation}\r\n		\\eta = 1 - \\frac{T_C}{T_H}\r\n	\\end{equation}\r\n	\r\n	28. Helmholtz Free Energy:\r\n	\\begin{equation}\r\n		F = U - TS\r\n	\\end{equation}\r\n	\r\n	29. Gibbs Free Energy:\r\n	\\begin{equation}\r\n		G = H - TS\r\n	\\end{equation}\r\n	\r\n	30. Heat Capacity:\r\n	\\begin{equation}\r\n		C = \\frac{dQ}{dT}\r\n	\\end{equation}\r\n	\r\n\\end{document}', NULL, NULL),
('48', '6', '4', '1', '\\documentclass{article}\r\n\\usepackage{amsmath}\r\n\r\n\\begin{document}\r\n\r\n\\title{Integration and Differential Equations in Physics}\r\n\\author{}\r\n\\date{}\r\n\\maketitle\r\n\r\n\\section*{Integral Equations}\r\n\r\n\\begin{enumerate}\r\n    \\item \\textbf{Indefinite Integral:}\r\n    \\[\r\n    \\int x^2 \\, dx = \\frac{x^3}{3} + C\r\n    \\]\r\n    \r\n    \\item \\textbf{Definite Integral:}\r\n    \\[\r\n    \\int_0^1 e^x \\, dx = e - 1\r\n    \\]\r\n    \r\n    \\item \\textbf{Integration by Parts:}\r\n    \\[\r\n    \\int x e^x \\, dx = x e^x - \\int e^x \\, dx = x e^x - e^x + C\r\n    \\]\r\n    \r\n    \\item \\textbf{Trigonometric Integral:}\r\n    \\[\r\n    \\int \\sin(x) \\, dx = -\\cos(x) + C\r\n    \\]\r\n    \r\n    \\item \\textbf{Exponential Integral:}\r\n    \\[\r\n    \\int e^{2x} \\, dx = \\frac{e^{2x}}{2} + C\r\n    \\]\r\n    \r\n    \\item \\textbf{Improper Integral:}\r\n    \\[\r\n    \\int_0^{\\infty} \\frac{1}{x^2+1} \\, dx = \\frac{\\pi}{2}\r\n    \\]\r\n    \r\n    \\item \\textbf{Surface Integral:}\r\n    \\[\r\n    \\iint_S \\mathbf{F} \\cdot d\\mathbf{S}\r\n    \\]\r\n    \r\n    \\item \\textbf{Volume Integral:}\r\n    \\[\r\n    \\iiint_V f(x, y, z) \\, dV\r\n    \\]\r\n    \r\n    \\item \\textbf{Line Integral:}\r\n    \\[\r\n    \\int_C \\mathbf{F} \\cdot d\\mathbf{r}\r\n    \\]\r\n    \r\n    \\item \\textbf{Gauss\'s Theorem:}\r\n    \\[\r\n    \\oint_S \\mathbf{E} \\cdot d\\mathbf{A} = \\frac{Q}{\\epsilon_0}\r\n    \\]\r\n\\end{enumerate}\r\n\r\n\\section*{Ordinary Differential Equations}\r\n\r\n\\begin{enumerate}\r\n    \\item \\textbf{First-Order ODE:}\r\n    \\[\r\n    \\frac{dy}{dx} = x^2 + y\r\n    \\]\r\n    \r\n    \\item \\textbf{Second-Order ODE:}\r\n    \\[\r\n    \\frac{d^2 y}{dx^2} - 3 \\frac{dy}{dx} + 2y = 0\r\n    \\]\r\n    \r\n    \\item \\textbf{Damped Harmonic Oscillator:}\r\n    \\[\r\n    m\\frac{d^2x}{dt^2} + b\\frac{dx}{dt} + kx = 0\r\n    \\]\r\n    \r\n    \\item \\textbf{Newtonâ€™s Second Law:}\r\n    \\[\r\n    F = m \\frac{d^2x}{dt^2}\r\n    \\]\r\n    \r\n    \\item \\textbf{Simple Harmonic Motion:}\r\n    \\[\r\n    \\frac{d^2 x}{dt^2} + \\omega^2 x = 0\r\n    \\]\r\n    \r\n    \\item \\textbf{RL Circuit:}\r\n    \\[\r\n    L \\frac{dI}{dt} + RI = V(t)\r\n    \\]\r\n\\end{enumerate}\r\n\r\n\\section*{Partial Differential Equations}\r\n\r\n\\begin{enumerate}\r\n    \\item \\textbf{Wave Equation:}\r\n    \\[\r\n    \\frac{\\partial^2 u}{\\partial t^2} = c^2 \\frac{\\partial^2 u}{\\partial x^2}\r\n    \\]\r\n    \r\n    \\item \\textbf{Heat Equation:}\r\n    \\[\r\n    \\frac{\\partial u}{\\partial t} = \\alpha \\frac{\\partial^2 u}{\\partial x^2}\r\n    \\]\r\n    \r\n    \\item \\textbf{Laplace\'s Equation:}\r\n    \\[\r\n    \\nabla^2 \\phi = 0\r\n    \\]\r\n    \r\n    \\item \\textbf{Poisson\'s Equation:}\r\n    \\[\r\n    \\nabla^2 \\phi = \\rho\r\n    \\]\r\n    \r\n    \\item \\textbf{SchrÃ¶dinger Equation:}\r\n    \\[\r\n    i\\hbar \\frac{\\partial \\psi}{\\partial t} = -\\frac{\\hbar^2}{2m} \\nabla^2 \\psi + V \\psi\r\n    \\]\r\n\\end{enumerate}\r\n\r\n\\end{document}', NULL, NULL),
('49', '6', '4', '2', '\\documentclass{article}\r\n\\usepackage{amsmath}\r\n\\usepackage{amssymb}\r\n\r\n\\title{Equations in Physics}\r\n\\author{}\r\n\\date{}\r\n\r\n\\begin{document}\r\n	\r\n	\\maketitle\r\n	\r\n	\\section*{Physics Equations}\r\n	\r\n	\\begin{enumerate}\r\n		\r\n		% Algebraic Equations\r\n		\\item \\textbf{Lorentz Force Law:}\r\n		\\begin{equation}\r\n			\\mathbf{F} = q (\\mathbf{E} + \\mathbf{v} \\times \\mathbf{B})\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Maxwellâ€™s Equations (Gaussâ€™s Law):}\r\n		\\begin{equation}\r\n			\\nabla \\cdot \\mathbf{E} = \\frac{\\rho}{\\epsilon_0}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Maxwellâ€™s Equations (Faradayâ€™s Law):}\r\n		\\begin{equation}\r\n			\\nabla \\times \\mathbf{E} = -\\frac{\\partial \\mathbf{B}}{\\partial t}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{General Relativity (Einstein Field Equation):}\r\n		\\begin{equation}\r\n			R_{\\mu \\nu} - \\frac{1}{2} R g_{\\mu \\nu} = \\frac{8 \\pi G}{c^4} T_{\\mu \\nu}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Energy-Mass Equivalence:}\r\n		\\begin{equation}\r\n			E = mc^2\r\n		\\end{equation}\r\n		\r\n		% Vector and Integral Equations\r\n		\\item \\textbf{Stokes\' Theorem:}\r\n		\\begin{equation}\r\n			\\int_S (\\nabla \\times \\mathbf{F}) \\cdot d\\mathbf{S} = \\oint_C \\mathbf{F} \\cdot d\\mathbf{r}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Divergence Theorem:}\r\n		\\begin{equation}\r\n			\\iiint_V (\\nabla \\cdot \\mathbf{F}) \\, dV = \\oint_S \\mathbf{F} \\cdot d\\mathbf{A}\r\n		\\end{equation}\r\n		\r\n		\r\n		% Quantum Mechanics\r\n		\\item \\textbf{Time-Dependent SchrÃ¶dinger Equation:}\r\n		\\begin{equation}\r\n			i \\hbar \\frac{\\partial \\psi}{\\partial t} = -\\frac{\\hbar^2}{2m} \\nabla^2 \\psi + V(x) \\psi\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Commutator Relation:}\r\n		\\begin{equation}\r\n			[\\hat{x}, \\hat{p}] = i \\hbar\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Expectation Value in Quantum Mechanics:}\r\n		\\begin{equation}\r\n			\\langle \\hat{O} \\rangle = \\int \\psi^* \\hat{O} \\psi \\, dx\r\n		\\end{equation}\r\n		\r\n		% Classical Mechanics\r\n		\\item \\textbf{Euler-Lagrange Equation:}\r\n		\\begin{equation}\r\n			\\frac{d}{dt} \\left( \\frac{\\partial L}{\\partial \\dot{q}} \\right) - \\frac{\\partial L}{\\partial q} = 0\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Hamiltonâ€™s Equations:}\r\n		\\begin{equation}\r\n			\\dot{q}_i = \\frac{\\partial H}{\\partial p_i}, \\quad \\dot{p}_i = -\\frac{\\partial H}{\\partial q_i}\r\n		\\end{equation}\r\n		\r\n		% Electromagnetism\r\n		\\item \\textbf{AmpÃ¨re\'s Law (Maxwell-AmpÃ¨re Law):}\r\n		\\begin{equation}\r\n			\\nabla \\times \\mathbf{B} = \\mu_0 \\mathbf{J} + \\mu_0 \\epsilon_0 \\frac{\\partial \\mathbf{E}}{\\partial t}\r\n		\\end{equation}\r\n		\r\n		% Fluid Dynamics\r\n		\\item \\textbf{Continuity Equation (Fluid Dynamics):}\r\n		\\begin{equation}\r\n			\\frac{\\partial \\rho}{\\partial t} + \\nabla \\cdot (\\rho \\mathbf{v}) = 0\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Bernoulli\'s Equation:}\r\n		\\begin{equation}\r\n			P + \\frac{1}{2} \\rho v^2 + \\rho gh = \\text{constant}\r\n		\\end{equation}\r\n		\r\n		% Cosmology and General Relativity\r\n		\\item \\textbf{Friedmann Equation:}\r\n		\\begin{equation}\r\n			\\left( \\frac{\\dot{a}}{a} \\right)^2 = \\frac{8 \\pi G}{3} \\rho - \\frac{k}{a^2} + \\frac{\\Lambda}{3}\r\n		\\end{equation}\r\n				\r\n		\r\n	\\end{enumerate}\r\n	\r\n\\end{document}', NULL, NULL),
('50', '6', '4', '3', '\\documentclass{article}\r\n\\usepackage{amsmath}\r\n\\usepackage{amssymb}\r\n\\usepackage{bm}   % For bold vectors\r\n\\usepackage{tensor} % For tensor notation\r\n\r\n\\title{Tensor and Physics Equations}\r\n\\author{}\r\n\\date{}\r\n\r\n\\begin{document}\r\n	\r\n	\\maketitle\r\n	\r\n	\\section*{Tensor and Advanced Physics Equations}\r\n	\r\n	\\begin{enumerate}\r\n		\r\n		% Tensor Equations\r\n		\\item \\textbf{Stress-Energy Tensor (General Relativity):}\r\n		\\begin{equation}\r\n			T^{\\mu \\nu} = (\\rho + p) u^\\mu u^\\nu + p g^{\\mu \\nu}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Einstein Field Equation (General Relativity):}\r\n		\\begin{equation}\r\n			R_{\\mu \\nu} - \\frac{1}{2} g_{\\mu \\nu} R = \\frac{8 \\pi G}{c^4} T_{\\mu \\nu}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Riemann Curvature Tensor:}\r\n		\\begin{equation}\r\n			R^\\rho_{\\sigma \\mu \\nu} = \\partial_\\mu \\Gamma^\\rho_{\\nu \\sigma} - \\partial_\\nu \\Gamma^\\rho_{\\mu \\sigma} + \\Gamma^\\rho_{\\mu \\lambda} \\Gamma^\\lambda_{\\nu \\sigma} - \\Gamma^\\rho_{\\nu \\lambda} \\Gamma^\\lambda_{\\mu \\sigma}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Ricci Tensor:}\r\n		\\begin{equation}\r\n			R_{\\mu \\nu} = R^\\lambda_{\\mu \\lambda \\nu}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Ricci Scalar:}\r\n		\\begin{equation}\r\n			R = g^{\\mu \\nu} R_{\\mu \\nu}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Christoffel Symbols of the Second Kind:}\r\n		\\begin{equation}\r\n			\\Gamma^\\lambda_{\\mu \\nu} = \\frac{1}{2} g^{\\lambda \\sigma} \\left( \\partial_\\mu g_{\\sigma \\nu} + \\partial_\\nu g_{\\sigma \\mu} - \\partial_\\sigma g_{\\mu \\nu} \\right)\r\n		\\end{equation}\r\n		\r\n		% Quantum Field Theory\r\n		\\item \\textbf{Dirac Equation (Relativistic Quantum Mechanics):}\r\n		\\begin{equation}\r\n			(i \\gamma^\\mu \\partial_\\mu - m) \\psi = 0\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Yang-Mills Field Strength Tensor:}\r\n		\\begin{equation}\r\n			F^a_{\\mu \\nu} = \\partial_\\mu A^a_\\nu - \\partial_\\nu A^a_\\mu + g f^{abc} A^b_\\mu A^c_\\nu\r\n		\\end{equation}\r\n		\r\n		% Electromagnetism\r\n		\\item \\textbf{Electromagnetic Field Tensor:}\r\n		\\begin{equation}\r\n			F_{\\mu \\nu} = \\partial_\\mu A_\\nu - \\partial_\\nu A_\\mu\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Maxwell\'s Equations in Tensor Form:}\r\n		\\begin{equation}\r\n			\\partial_\\mu F^{\\mu \\nu} = \\mu_0 J^\\nu\r\n		\\end{equation}\r\n		\r\n		% Fluid Dynamics\r\n		\\item \\textbf{Navier-Stokes Equation (Fluid Dynamics):}\r\n		\\begin{equation}\r\n			\\rho \\left( \\frac{\\partial \\mathbf{v}}{\\partial t} + (\\mathbf{v} \\cdot \\nabla) \\mathbf{v} \\right) = - \\nabla p + \\mu \\nabla^2 \\mathbf{v} + \\rho \\mathbf{g}\r\n		\\end{equation}\r\n		\r\n		% Statistical Mechanics\r\n		\\item \\textbf{Partition Function (Statistical Mechanics):}\r\n		\\begin{equation}\r\n			Z = \\sum_i e^{-\\beta E_i}\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Boltzmann Distribution:}\r\n		\\begin{equation}\r\n			f(E) = \\frac{1}{Z} e^{-\\beta E}\r\n		\\end{equation}\r\n		\r\n		% Cosmology\r\n		\\item \\textbf{Robertson-Walker Metric (Cosmology):}\r\n		\\begin{equation}\r\n			ds^2 = -c^2 dt^2 + a(t)^2 \\left( \\frac{dr^2}{1 - kr^2} + r^2 d\\Omega^2 \\right)\r\n		\\end{equation}\r\n		\r\n		\\item \\textbf{Friedmann Equation (Cosmology):}\r\n		\\begin{equation}\r\n			\\left( \\frac{\\dot{a}}{a} \\right)^2 = \\frac{8 \\pi G}{3} \\rho - \\frac{k}{a^2} + \\frac{\\Lambda}{3}\r\n		\\end{equation}\r\n		\r\n		% Quantum Electrodynamics\r\n		\\item \\textbf{QED Interaction Lagrangian:}\r\n		\\begin{equation}\r\n			\\mathcal{L} = \\bar{\\psi}(i \\gamma^\\mu D_\\mu - m) \\psi - \\frac{1}{4} F_{\\mu \\nu} F^{\\mu \\nu}\r\n		\\end{equation}\r\n		\r\n		% Thermodynamics\r\n		\\item \\textbf{Clausius-Clapeyron Equation (Phase Transitions):}\r\n		\\begin{equation}\r\n			\\frac{dP}{dT} = \\frac{L}{T \\Delta V}\r\n		\\end{equation}\r\n		\r\n		% Generalized Force in Lagrangian Mechanics\r\n		\\item \\textbf{Lagrange\'s Equation of Motion:}\r\n		\\begin{equation}\r\n			\\frac{d}{dt} \\left( \\frac{\\partial L}{\\partial \\dot{q}_i} \\right) - \\frac{\\partial L}{\\partial q_i} = Q_i\r\n		\\end{equation}\r\n		\r\n		% Nonlinear Dynamics\r\n		\\item \\textbf{Lorenz System (Nonlinear Dynamics):}\r\n		\\begin{equation}\r\n			\\frac{dx}{dt} = \\sigma (y - x), \\quad \\frac{dy}{dt} = x(\\rho - z) - y, \\quad \\frac{dz}{dt} = xy - \\beta z\r\n		\\end{equation}\r\n		\r\n		% Advanced Electromagnetism\r\n		\\item \\textbf{LiÃ©nard-Wiechert Potentials (Electrodynamics):}\r\n		\\begin{equation}\r\n			\\mathbf{A}(\\mathbf{r}, t) = \\frac{\\mu_0}{4 \\pi} \\int \\frac{J(\\mathbf{r}\', t_r)}{|\\mathbf{r} - \\mathbf{r}\'|} d^3r\'\r\n		\\end{equation}\r\n		\r\n	\\end{enumerate}\r\n	\r\n\\end{document}', NULL, NULL);
