('74', '9', '1', '2', '\\documentclass{article}\r\n\\usepackage{hyperref}\r\n\\begin{document}\r\n	\r\n	\\section{Introduction}\r\n	This is an introduction to physics. See \\cite{ref1} for more details.\r\n	\r\n	\\begin{thebibliography}{99}\r\n		\\bibitem{ref1} Halliday, D., Resnick, R. \\& Walker, J. (2013). \\textit{Fundamentals of Physics}. Wiley. \\url{https://www.wiley.com/en-us/Fundamentals+of+Physics%2C+10th+Edition-p-9781119495267}\r\n	\\end{thebibliography}\r\n	\r\n\\end{document}', NULL, NULL),
('75', '9', '1', '3', '\\documentclass{article}\r\n\\usepackage{hyperref}\r\n\\begin{document}\r\n	\r\n	\\section{Overview}\r\n	Refer to \\cite{ref1, ref2} for comprehensive information.\r\n	\\newpage\r\n	\\begin{thebibliography}{99}\r\n		\\bibitem{ref1} Halliday, D., Resnick, R. \\& Walker, J. (2013). \\textit{Fundamentals of Physics}. Wiley. \\url{https://www.wiley.com/en-us/Fundamentals+of+Physics%2C+10th+Edition-p-9781119495267}\r\n		\\bibitem{ref2} Young, H. D. \\& Freedman, R. A. (2014). \\textit{University Physics}. Pearson. \\url{https://www.pearson.com/store/p/university-physics/P100000934291}\r\n	\\end{thebibliography}\r\n	\r\n\\end{document}', NULL, NULL),
('76', '9', '1', '4', '\\documentclass{article}\r\n\\usepackage{hyperref}\r\n\\title{Hyperlinked Edited Books}\r\n\\begin{document}\r\n\\maketitle\r\n\r\n\\section{Further Reading}\r\nFor further reading, see \\cite{ref1}.\r\n\\newpage\r\n\\begin{thebibliography}{99}\r\n\\bibitem{ref1} Brown, L. (Ed.). (2018). \\textit{Modern Physics: A Comprehensive Guide}. Springer. \\url{https://link.springer.com/book/10.1007/978-3-319-74760-5}\r\n\\end{thebibliography}\r\n\r\n\\end{document}', NULL, NULL),
('77', '9', '1', '5', '\\documentclass{book}\r\n\\usepackage{hyperref}\r\n\\usepackage{amsmath}\r\n\\usepackage{amsfonts}\r\n\\usepackage{graphicx}\r\n\r\n\\title{Introduction to Physics}\r\n\\author{}\r\n\\date{}\r\n\r\n\\begin{document}\r\n	\r\n	\\maketitle\r\n	\r\n	\\tableofcontents\r\n	\\newpage\r\n	\r\n	\\chapter{Classical Mechanics}\r\n	\\section{Newton\'s Laws of Motion}\r\n	\\subsection{First Law}\r\n	An object at rest stays at rest, and an object in motion stays in motion unless acted upon by a net external force.\r\n	\r\n	\\subsection{Second Law}\r\n	The acceleration of an object is directly proportional to the net force acting on it and inversely proportional to its mass.\r\n	\\begin{equation}\r\n		F = ma\r\n	\\end{equation}\r\n	\r\n	\\subsubsection{Example}\r\n	If a force of 10 N acts on a 2 kg mass, the acceleration can be calculated as:\r\n	\\[\r\n	a = \\frac{F}{m} = \\frac{10 \\, \\text{N}}{2 \\, \\text{kg}} = 5 \\, \\text{m/s}^2\r\n	\\]\r\n	\r\n	\\section{Energy Conservation}\r\n	The total mechanical energy in a closed system remains constant.\r\n	\r\n	\\subsection{Kinetic Energy}\r\n	The kinetic energy of an object is given by:\r\n	\\begin{equation}\r\n		KE = \\frac{1}{2}mv^2\r\n	\\end{equation}\r\n	\r\n	\\chapter{Thermodynamics}\r\n	\\section{Laws of Thermodynamics}\r\n	\\subsection{Zeroth Law}\r\n	If two systems are each in thermal equilibrium with a third system, then they are in thermal equilibrium with each other.\r\n	\r\n	\\subsection{First Law}\r\n	Energy cannot be created or destroyed, only transformed.\r\n	\\begin{equation}\r\n		\\Delta U = Q - W\r\n	\\end{equation}\r\n	\r\n	\\chapter{Electromagnetism}\r\n	\\section{Electrostatics}\r\n	\\subsection{Coulomb\'s Law}\r\n	The force between two charges is given by:\r\n	\\begin{equation}\r\n		F = k \\frac{|q_1 q_2|}{r^2}\r\n	\\end{equation}\r\n	\r\n	\\subsection{Electric Field}\r\n	The electric field \\( E \\) due to a point charge is defined as:\r\n	\\begin{equation}\r\n		E = k \\frac{|q|}{r^2}\r\n	\\end{equation}\r\n	\r\n	\\chapter{Modern Physics}\r\n	\\section{Quantum Mechanics}\r\n	\\subsection{Wave-Particle Duality}\r\n	Light exhibits both wave-like and particle-like properties.\r\n	\r\n	\\subsection{Uncertainty Principle}\r\n	The position and momentum of a particle cannot both be precisely measured at the same time.\r\n	\r\n	\\section{References}\r\n	\\begin{thebibliography}{99}\r\n		\\bibitem{ref1} Halliday, D., Resnick, R., \\& Walker, J. (2013). \\textit{Fundamentals of Physics}. Wiley. \\url{https://www.wiley.com/en-us/Fundamentals+of+Physics%2C+10th+Edition-p-9781119495267}\r\n		\\bibitem{ref2} Young, H. D., \\& Freedman, R. A. (2014). \\textit{University Physics}. Pearson. \\url{https://www.pearson.com/store/p/university-physics/P100000934291}\r\n		\\bibitem{ref3} Feynman, R. P., Leighton, R., \\& Sands, M. (1965). \\textit{The Feynman Lectures on Physics}. Addison-Wesley. \\url{https://www.feynmanlectures.caltech.edu}\r\n	\\end{thebibliography}\r\n	\r\n\\end{document}', NULL, NULL),
