('106', '10', '3', '12', '\\documentclass{article}\r\n\\usepackage{tikz}\r\n\r\n\\title{Electric Field Lines Example}\r\n\\begin{document}\r\n\\maketitle\r\n\r\n\\begin{tikzpicture}\r\n    % Draw positive charge\r\n    \\fill[red] (-2,0) circle (3mm);\r\n    \\node at (-2,0.5) {$+q$};\r\n    \r\n    % Draw negative charge\r\n    \\fill[blue] (2,0) circle (3mm);\r\n    \\node at (2,0.5) {$-q$};\r\n    \r\n    % Draw field lines\r\n    \\foreach \\x in {0,30,...,360} {\r\n        \\draw[->, thick] (-2,0) -- ++(\\x:3cm);\r\n        \\draw[->, thick] (2,0) -- ++(\\x+180:3cm);\r\n    }\r\n\\end{tikzpicture}\r\n\r\n\\end{document}', NULL, NULL),
