('111', '10', '1', '5', '\\documentclass{article}\r\n\\usepackage{tikz}\r\n\\usepackage[utf8]{inputenc}\r\n\r\n\\title{Quotation with Curved Background}\r\n\\begin{document}\r\n	\\maketitle\r\n	\r\n	\\begin{tikzpicture}\r\n		\\fill[green!20] (0,0) .. controls (0,2) and (2,2) .. (2,0) -- (2,-4) .. controls (2,-2) and (0,-2) .. (0,-4) -- cycle;\r\n		\\node at (1, -2) [font=\\itshape] {\r\n			``The future belongs to those who believe in the beauty of their dreams.\'\'\r\n		};\r\n	\\end{tikzpicture}\r\n	\r\n\\end{document}', NULL, NULL),
