('12', '5', '1', '2', '#Scatter plot\r\nimport matplotlib.pyplot as plt\r\n\r\nx = [1, 2, 3, 4, 5]\r\ny = [2, 4, 6, 8, 10]\r\n\r\nplt.scatter(x, y)\r\nplt.title(\'Scatter Plot\')\r\nplt.xlabel(\'X-axis\')\r\nplt.ylabel(\'Y-axis\')\r\nplt.savefig(\'scatter_plot.png\')\r\nplt.show()\r\n', 'Basic Scatter Plot', ''),
