('30', '1', '2', '2', '\'\'\'float data type\'\'\'\r\nvalue = 74\r\nif type(value) == float:\r\n    print(f\"{value} is a float\")\r\nelse:\r\n    print(f\"{value} is not a float\")\r\n\r\nvalue = 510.12\r\nif type(value) == float:\r\n    print(f\"{value} is a float\")\r\nelse:\r\n    print(f\"{value} is not a float\")', NULL, ''),
