('112', '2', '1', '4', '\'\'\'Indexing\'\'\'\r\nA = [2, 3.4, 5, 6, 4, 3, \'abc\', 2, \'def\', 8.5, 9.3, 3]\r\nprint(A[0]) #1st element\r\nprint(A[1]) #2nd element\r\nprint(A[2]) #3rd element\r\nprint(A[-1])#last element\r\nprint(A[-2]) #element before last\r\n', NULL, ''),
('113', '2', '1', '5', '\'\'\'Slicing\'\'\'\r\nA = [2, 6, 9, 5, 4, 1, 9, 1, 5, 8]\r\nprint(\'slice index 2 to 6 in step 1\', A[2:7]) #step = 1 default\r\nprint(\'slice index 2 to 8 in step 2\', A[2:9:2])\r\nprint(\'slice index 2 to the end\', A[2:])\r\nprint(\'slice index 0 to 5\', A[:6])', NULL, ''),
('114', '2', '1', '6', '\'\'\'Built in Function in List\'\'\'\r\n\r\nA = [9, 6, 5, 5, 8, 8, 8, 8, 4, 9, 6]\r\n\r\nL = len(A) #total no of items\r\nprint(\'total no of items\',L)\r\nsum = sum(A) # sum of all items\r\nprint(\'Sum of all nos in the list\',sum)\r\nmx = max(A)\r\nprint(\'Maxmum value\', mx)\r\nmn = min(A)\r\nprint(\'Minimum value\', mn)\r\nsort= sorted(A)\r\nprint(\'sort in ascending order\', sort)\r\nrev_sort = sorted(A, reverse=True)\r\nprint(\'sort in descending order\', rev_sort)\r\n\r\nB = [\'python\', \'latex\', \'gnuplot\', \'arduino\']\r\nsort = sorted(B)\r\nprint(\'Sort ascending alphabetically\', sort)', NULL, ''),
('115', '3', '2', '1', 'def prime(n):\r\n    if n < 2:  \r\n        return \'not prime\'\r\n    for i in range(2, int(n**0.5) + 1):  \r\n        if n % i == 0:\r\n            return \'not prime\'\r\n    return \'prime\'\r\n\r\nn = 49\r\nprint(prime(n))', '        <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\r\n\r\n    <h4>Input:</h4>\r\n    <p>Given number \\( n \\) (e.g., \\( n = 49 \\)).</p>\r\n\r\n    <h4>Check if \\( n < 2 \\):</h4>\r\n    <p>If \\( n \\) is less than 2, return \'not prime\'. (This is because prime numbers are defined as greater than 1.)</p>\r\n\r\n    <h4>Initialize Loop:</h4>\r\n    <p>Loop through all integers \\( i \\) from 2 to the integer value of the square root of \\( n \\) (inclusive). This is done using the range:</p>\r\n    <p>\r\n        <code>for i in range(2, int(n**0.5) + 1)</code>\r\n    </p>\r\n\r\n    <h4>Check for Divisibility:</h4>\r\n    <p>For each \\( i \\) in the loop:</p>\r\n    <p>If \\( n \\) is divisible by \\( i \\) (i.e., if \\( n \\mod i == 0 \\)): return \'not prime\'. (This means that \\( n \\) has a divisor other than 1 and itself.)</p>\r\n\r\n    <h4>Return Result:</h4>\r\n    <p>If no divisors were found in the loop, return \'prime\'.</p>\r\n\r\n    <h4>Output:</h4>\r\n    <p>Call the <code>prime(n)</code> function and print the result.</p>\r\n\r\n    <h4>Example Walkthrough</h4>\r\n    <p>For \\( n = 49 \\):</p>\r\n    <ul>\r\n        <li>Check if \\( 49 < 2 \\): False (continue to next step).</li>\r\n        <li>Loop through \\( i = 2 \\) to \\( 7 \\) (the square root of \\( 49 \\) is \\( 7 \\)): \r\n            <ul>\r\n                <li>i = 2: \\( 49 \\mod 2 \\neq 0 \\) (continue).</li>\r\n                <li>i = 3: \\( 49 \\mod 3 \\neq 0 \\) (continue).</li>\r\n                <li>i = 4: \\( 49 \\mod 4 \\neq 0 \\) (continue).</li>\r\n                <li>i = 5: \\( 49 \\mod 5 \\neq 0 \\) (continue).</li>\r\n                <li>i = 6: \\( 49 \\mod 6 \\neq 0 \\) (continue).</li>\r\n                <li>i = 7: \\( 49 \\mod 7 = 0 \\) (return \'not prime\').</li>\r\n            </ul>\r\n        </li>\r\n    </ul>', ''),
('116', '3', '3', '2', '#Finding out prime number greater than or lesser than a given value\r\n\r\ndef prime(num):\r\n    for i in range(2, num):\r\n        if num % i == 0:\r\n            return False\r\n    return True\r\n\r\ndef next_prime(num):\r\n    num += 1\r\n    while not prime(num):\r\n        num += 1\r\n    return num\r\n\r\ndef previous_prime(num):\r\n    num -= 1\r\n    while not prime(num):\r\n        num -= 1\r\n    return num\r\n\r\n\r\ngiven_value = 27\r\n\r\nnext_prime_greater = next_prime(given_value)\r\nprevious_prime_lesser = previous_prime(given_value)\r\n\r\nprint(f\"The next prime number greater than {given_value} is {next_prime_greater}.\")\r\nprint(f\"The previous prime number lesser than {given_value} is {previous_prime_lesser}.\")\r\n', NULL, ''),
('117', '2', '1', '7', '\'\'\'concatenate two list\'\'\'\r\nA = [9, 6, 5, 5, 8, 8, 8, 8, 4, 9, 6]\r\nB = [\'python\', \'latex\', \'gnuplot\', \'arduino\']\r\nC = A + B\r\nprint(\'concatenate list = \',C)\r\nprint(\'\\n\')\r\n\r\n\'\'\'Location of an element\'\'\'\r\nA = [1,2,3,4,5,6,7,8,9]\r\nprint(\'location of 5=\', A.index(5))\r\nprint(\'\\n\')\r\n\r\n\'\'\'find location of minimum value in list\'\'\'\r\nA = [1,2,3,4,5,6,7,8,9]\r\nprint(\'location of min value =\', A.index(min(A)))\r\nprint(\'\\n\')\r\n\r\n\'\'\'Reverse the list\'\'\'\r\nA = [1,2,3,4,5,6,7,8,9]\r\nA.reverse()\r\nprint(\'Reversed list = \', A)', NULL, ''),
('118', '2', '1', '8', '\'\'\'Append element\'\'\'\r\nA = [1, 8, 4, 3, 8, 4, 9, 9, 9, 6]\r\nA.append(5) # Put 5 at the end\r\nprint(\'updated list = \',A)\r\nprint(\'\\n\')\r\n\r\n\'\'\'Remove element from end\'\'\' \r\nA = [1, 8, 4, 3, 8, 4, 9, 9, 9, 6]\r\nA.pop() \r\nprint(\'updated list = \',A)\r\nprint(\'\\n\')\r\n\r\n\'\'\'Remove element from particular position\'\'\' \r\nA = [1, 8, 4, 3, 8, 4, 9, 9, 9, 6]\r\nA.pop(5) \r\nprint(\'updated list = \',A)\r\nprint(\'\\n\')\r\n\r\n\'\'\'Remove particular element \'\'\' \r\nA = [1, 8, 4, 3, 12, 4, 9, 19, 29, 6]\r\nA.remove(19) \r\nprint(\'updated list = \',A)', NULL, ''),
('119', '2', '1', '9', '\'\'\'Insert element to particular position\'\'\'\r\nA = [1, 8, 4, 3, 8, 4, 9, 9, 9, 6]\r\nA.insert(5, 13) \r\nprint(\'updated list = \',A)\r\nprint(\'\\n\')\r\n\r\n\'\'\'Replace an item at particular position\'\'\'\r\nA = [1, 8, 4, 3, 8, 4, 9, 9, 9, 6]\r\nA[4] = 13 \r\nprint(\'updated list = \',A)\r\nprint(\'\\n\')\r\n\r\n\'\'\'Count occurance of particular element\'\'\'\r\nA = [1, 8, 4, 3, 8, 4, 9, 9, 9, 6]\r\nC = A.count(9) \r\nprint(\'Total No. of 9 in the list = \',C)\r\n\r\n\'\'\'Delete a segment\'\'\'\r\nA = [1, 8, 4, 3, 8, 4, 9, 9, 9, 6]\r\ndel A[2:5]\r\nprint(\'updated list = \',A)', NULL, ''),
('120', '2', '1', '10', '\'\'\'List comprehension\'\'\'\r\n\r\n\'\'\'Square of List\'\'\'\r\nA = [9, 6, 5, 5, 8, 8, 8, 8, 4, 9, 6]\r\nB = [i**2 for i in A]\r\nprint(B)\r\nprint(\'\\n\')\r\n\r\n\'\'\'find even numbers\'\'\'\r\nA = [9, 6, 5, 5, 8, 8, 8, 8, 4, 9, 6]\r\nB = [i for i in A if i%2 == 0]\r\nprint(B)\r\nprint(\'\\n\')\r\n\r\n\'\'\'uppercase conversion\'\'\'\r\nfruits = [\"apple\", \"banana\", \"cherry\"]\r\nuppercase_fruits = [fruit.upper() for fruit in fruits]\r\nprint(uppercase_fruits)\r\nprint(\'\\n\')\r\n\r\n\'\'\'length of words\'\'\'\r\nwords = [\"hello\", \"world\", \"python\"]\r\nlengths = [len(word) for word in words]\r\nprint(lengths)', NULL, ''),
('121', '2', '1', '11', '\'\'\'Creating a nested list\'\'\'\r\nmatrix = [[1, 2, 3],\r\n    [4, 5, 6],\r\n    [7, 8, 9]]\r\n\r\n\'\'\'Accessing elements in a nested list\'\'\'\r\nprint(\"Element at row 1, column 2:\", matrix[0][1])  \r\nprint(\"Element at row 2, column 3:\", matrix[1][2])\r\n\r\n\'\'\'Looping through a nested list\'\'\'\r\nfor row in matrix:\r\n    for element in row:\r\n        print(element, end=\" \")\r\n    print()\r\n    \r\n\'\'\'Summing all elements in the nested list\'\'\'\r\ntotal_sum = 0\r\nfor row in matrix:\r\n    total_sum += sum(row)\r\n    \r\nprint(\"Sum of all elements in the matrix:\", total_sum)', NULL, ''),
