('180', '5', '10', '3', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\n\r\n# Define grid\r\nx = np.linspace(-5, 5, 100)\r\ny = np.linspace(-5, 5, 100)\r\nX, Y = np.meshgrid(x, y)\r\n\r\n# Gravitational potential (inverse square law)\r\nG = 6.67430e-11  # Gravitational constant\r\nM = 1.0  # Mass\r\nr = np.sqrt(X**2 + Y**2)\r\nZ = -G * M / r\r\n\r\n# Create contour plot\r\nplt.contour(X, Y, Z, levels=50)\r\nplt.title(\'Gravitational Potential Near a Massive Object\')\r\nplt.xlabel(\'X-axis\')\r\nplt.ylabel(\'Y-axis\')\r\nplt.colorbar()\r\nplt.savefig(\'plot.png\')\r\nplt.show()\r\n', 'Gravitational Potential Near a Massive Object', ''),
('181', '5', '10', '4', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\n\r\n# Define grid\r\nx = np.linspace(-5, 5, 100)\r\ny = np.linspace(-5, 5, 100)\r\nX, Y = np.meshgrid(x, y)\r\n\r\n# Wave interference\r\nr1 = np.sqrt((X + 1)**2 + Y**2)\r\nr2 = np.sqrt((X - 1)**2 + Y**2)\r\nZ = np.sin(r1) + np.sin(r2)\r\n\r\n# Create contour plot\r\nplt.contour(X, Y, Z, levels=50)\r\nplt.title(\'Wave Interference Pattern\')\r\nplt.xlabel(\'X-axis\')\r\nplt.ylabel(\'Y-axis\')\r\nplt.colorbar()\r\nplt.savefig(\'plot.png\')\r\nplt.show()', 'Wave Interference Pattern ', ''),
('182', '5', '10', '5', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\n\r\n# Define grid\r\nx = np.linspace(-5, 5, 100)\r\ny = np.linspace(-5, 5, 100)\r\nX, Y = np.meshgrid(x, y)\r\n\r\n# Probability density function\r\nZ = np.exp(-(X**2 + Y**2)) * (X**2 + Y**2)\r\n\r\n# Create contour plot\r\nplt.contour(X, Y, Z, levels=50)\r\nplt.title(\'Quantum Harmonic Oscillator Probability Density\')\r\nplt.xlabel(\'X-axis\')\r\nplt.ylabel(\'Y-axis\')\r\nplt.colorbar()\r\nplt.savefig(\'plot.png\')\r\nplt.show()', 'Quantum Harmonic Oscillator Probability Density', ''),
('183', '5', '10', '6', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\n\r\n# Define grid\r\nx = np.linspace(-5, 5, 100)\r\ny = np.linspace(-5, 5, 100)\r\nX, Y = np.meshgrid(x, y)\r\n\r\n# 2D potential well function\r\nZ = (X**2 + Y**2)\r\n\r\n# Create contour plot\r\nplt.contour(X, Y, Z, levels=50)\r\nplt.title(\'2D Potential Well Contour Plot\')\r\nplt.xlabel(\'X-axis\')\r\nplt.ylabel(\'Y-axis\')\r\nplt.colorbar()\r\nplt.savefig(\'plot.png\')\r\nplt.show()', '2d Potential Well Contour ', ''),
('184', '5', '10', '7', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\n\r\n# Define grid\r\nx = np.linspace(-5, 5, 100)\r\ny = np.linspace(-5, 5, 100)\r\nX, Y = np.meshgrid(x, y)\r\n\r\n# Electric potential of a dipole\r\nr1 = np.sqrt((X + 1)**2 + Y**2)\r\nr2 = np.sqrt((X - 1)**2 + Y**2)\r\nZ = 1 / r1 - 1 / r2\r\n\r\n# Create contour plot\r\nplt.contour(X, Y, Z, levels=50)\r\nplt.title(\'Electric Dipole Potential in 2D\')\r\nplt.xlabel(\'X-axis\')\r\nplt.ylabel(\'Y-axis\')\r\nplt.colorbar()\r\nplt.savefig(\'plot.png\')\r\nplt.show()', NULL, ''),
('185', '5', '10', '8', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\n\r\n# Constants\r\na0 = 1  # Bohr radius, set to 1 for simplicity (in atomic units)\r\n\r\n# Define the radial wave function for hydrogen atom (n=1, l=0)\r\ndef hydrogen_wavefunction(r):\r\n    return (1 / np.sqrt(np.pi * a0**3)) * np.exp(-r / a0)\r\n\r\n# Define the probability density\r\ndef probability_density(r):\r\n    psi = hydrogen_wavefunction(r)\r\n    return np.abs(psi)**2\r\n\r\n# Define grid in 2D (in x and y plane)\r\nx = np.linspace(-5, 5, 200)\r\ny = np.linspace(-5, 5, 200)\r\nX, Y = np.meshgrid(x, y)\r\n\r\n# Convert to radial coordinate r (since it\'s spherical symmetry, use r = sqrt(x^2 + y^2))\r\nR = np.sqrt(X**2 + Y**2)\r\n\r\n# Calculate the probability density\r\nZ = probability_density(R)\r\n\r\n# Plot the contour plot of the probability density\r\nplt.contourf(X, Y, Z, levels=50, cmap=\'viridis\')\r\nplt.title(\'Probability Density of Electron in Hydrogen Atom (n=1, l=0)\')\r\nplt.xlabel(\'x (Bohr radii)\')\r\nplt.ylabel(\'y (Bohr radii)\')\r\nplt.colorbar(label=\'Probability Density\')\r\nplt.savefig(\'plot.png\')\r\nplt.show()\r\n', 'Probability density of H like atom Contour Plot', ''),
('186', '5', '10', '9', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\n\r\n# Constants\r\na0 = 1  # Bohr radius, set to 1 for simplicity (in atomic units)\r\n\r\n# Define the radial wavefunction for n=2, l=1\r\ndef radial_wavefunction(r):\r\n    return (1 / np.sqrt(24 * a0**3)) * (r / a0) * np.exp(-r / (2 * a0))\r\n\r\n# Define the probability density\r\ndef probability_density(r, theta):\r\n    R = radial_wavefunction(r)\r\n    angular_part = np.cos(theta)**2  # Angular dependence for l=1, m=0\r\n    return np.abs(R)**2 * angular_part\r\n\r\n# Define grid in 2D (in x and y plane)\r\nx = np.linspace(-10, 10, 200)\r\ny = np.linspace(-10, 10, 200)\r\nX, Y = np.meshgrid(x, y)\r\n\r\n# Convert to radial coordinate r and angular coordinate theta\r\nR = np.sqrt(X**2 + Y**2)\r\nTheta = np.arctan2(Y, X)\r\n\r\n# Calculate the probability density\r\nZ = probability_density(R, Theta)\r\n\r\n# Plot the contour plot of the probability density\r\nplt.contourf(X, Y, Z, levels=50, cmap=\'plasma\')\r\nplt.title(\'Probability Density of Electron in Hydrogen Atom (n=2, l=1)\')\r\nplt.xlabel(\'x (Bohr radii)\')\r\nplt.ylabel(\'y (Bohr radii)\')\r\nplt.colorbar(label=\'Probability Density\')\r\nplt.savefig(\'plot.png\')\r\nplt.show()', 'Probability density of H like atom Contour Plot', ''),
('187', '5', '10', '10', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\n\r\n# Constants\r\na0 = 1  # Bohr radius, set to 1 for simplicity (in atomic units)\r\n\r\n# Define the radial wavefunction for n=3, l=1 (3p orbital)\r\ndef radial_wavefunction_n3_l1(r):\r\n    return (1 / (81 * np.sqrt(6 * a0**3))) * (6 - r / a0) * (r / a0) * np.exp(-r / (3 * a0))\r\n\r\n# Define the radial wavefunction for n=3, l=2 (3d orbital)\r\ndef radial_wavefunction_n3_l2(r):\r\n    return (1 / (81 * np.sqrt(30 * a0**3))) * (r / a0)**2 * np.exp(-r / (3 * a0))\r\n\r\n# Define the probability density for n=3, l=1 (3p orbital)\r\ndef probability_density_n3_l1(r, theta):\r\n    R = radial_wavefunction_n3_l1(r)\r\n    angular_part = np.cos(theta)**2  # Angular dependence for l=1, m=0 (p-orbital)\r\n    return np.abs(R)**2 * angular_part\r\n\r\n# Define the probability density for n=3, l=2 (3d orbital)\r\ndef probability_density_n3_l2(r, theta):\r\n    R = radial_wavefunction_n3_l2(r)\r\n    angular_part = np.sin(theta)**2  # Angular dependence for l=2, m=0 (d-orbital approximation)\r\n    return np.abs(R)**2 * angular_part\r\n\r\n# Define grid in 2D (in x and y plane)\r\nx = np.linspace(-15, 15, 300)\r\ny = np.linspace(-15, 15, 300)\r\nX, Y = np.meshgrid(x, y)\r\n\r\n# Convert to radial coordinate r and angular coordinate theta\r\nR = np.sqrt(X**2 + Y**2)\r\nTheta = np.arctan2(Y, X)\r\n\r\n# Calculate the probability density for n=3, l=1 (3p orbital)\r\nZ_n3_l1 = probability_density_n3_l1(R, Theta)\r\n\r\n# Calculate the probability density for n=3, l=2 (3d orbital)\r\nZ_n3_l2 = probability_density_n3_l2(R, Theta)\r\n\r\n# Plot the contour plot for n=3, l=1 (3p orbital)\r\nplt.figure(figsize=(12, 6))\r\n\r\nplt.subplot(1, 2, 1)\r\nplt.contourf(X, Y, Z_n3_l1, levels=50, cmap=\'plasma\')\r\nplt.title(\'Probability Density for Hydrogen Atom (n=3, l=1, 3p)\')\r\nplt.xlabel(\'x (Bohr radii)\')\r\nplt.ylabel(\'y (Bohr radii)\')\r\nplt.colorbar(label=\'Probability Density\')\r\n\r\n# Plot the contour plot for n=3, l=2 (3d orbital)\r\nplt.subplot(1, 2, 2)\r\nplt.contourf(X, Y, Z_n3_l2, levels=50, cmap=\'viridis\')\r\nplt.title(\'Probability Density for Hydrogen Atom (n=3, l=2, 3d)\')\r\nplt.xlabel(\'x (Bohr radii)\')\r\nplt.ylabel(\'y (Bohr radii)\')\r\nplt.colorbar(label=\'Probability Density\')\r\n\r\nplt.tight_layout()\r\nplt.savefig(\'plot.png\')\r\nplt.show()', 'Probability density of H like atom Contour Plot', ''),
('188', '5', '11', '1', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\nfrom mpl_toolkits.mplot3d import Axes3D\r\n\r\n# Parameters for the projectile\r\nv0 = 50  # initial velocity\r\ntheta = np.pi / 4  # launch angle\r\ng = 9.81  # gravity\r\n\r\n# Time of flight\r\nt = np.linspace(0, 2 * v0 * np.sin(theta) / g, 100)\r\n\r\n# Define the trajectory\r\nx = v0 * np.cos(theta) * t\r\ny = v0 * np.sin(theta) * t - 0.5 * g * t**2\r\nz = np.zeros_like(t)\r\n\r\n# Plotting the trajectory\r\nfig = plt.figure()\r\nax = fig.add_subplot(111, projection=\'3d\')\r\nax.plot(x, y, z, label=\'Projectile Trajectory\')\r\nax.set_title(\"3D Projectile Trajectory\")\r\nplt.savefig(\'plot.png\')\r\nplt.show()', 'Trajectory of a projectile in 3D', ''),
('189', '5', '11', '2', 'import numpy as np\r\nimport matplotlib.pyplot as plt\r\nfrom mpl_toolkits.mplot3d import Axes3D\r\n\r\n# Define the magnetic field\r\ndef magnetic_field(x, y, z):\r\n    return -y / (x**2 + y**2), x / (x**2 + y**2), np.zeros_like(x)\r\n\r\nx, y, z = np.meshgrid(np.linspace(-5, 5, 10), np.linspace(-5, 5, 10), np.linspace(-5, 5, 10))\r\n\r\n# Plotting the magnetic field lines\r\nfig = plt.figure()\r\nax = fig.add_subplot(111, projection=\'3d\')\r\nax.quiver(x, y, z, *magnetic_field(x, y, z))\r\nax.set_title(\"Magnetic Field Around a Current-Carrying Wire\")\r\nplt.savefig(\'plot.png\')\r\nplt.show()', ' 3D Magnetic Field Lines Around a Current-Carrying Wire', ''),
