('360', '2', '3', '2', 'print(\"\\n========== 1. CREATING STRINGS ==========\")\r\n\r\n# Simple strings\r\nexperiment = \"Photoelectric Effect\"\r\nunit = \"eV\"\r\n\r\nprint(\"Experiment:\", experiment)\r\nprint(\"Unit:\", unit)\r\n\r\n\r\nprint(\"\\n========== 2. STRING LENGTH ==========\")\r\n\r\nprint(\"Length of experiment name:\", len(experiment))\r\n\r\n\r\nprint(\"\\n========== 3. STRING INDEXING ==========\")\r\n\r\n# Indexing (starts from 0)\r\nprint(\"First character:\", experiment[0])\r\nprint(\"Last character:\", experiment[-1])\r\n\r\n\r\nprint(\"\\n========== 4. STRING SLICING ==========\")\r\n\r\nprint(\"First 6 characters:\", experiment[0:6])\r\nprint(\"Last 6 characters:\", experiment[-6:])\r\nprint(\"Every second character:\", experiment[::2])\r\n\r\n\r\nprint(\"\\n========== 5. UPPERCASE & LOWERCASE ==========\")\r\n\r\nprint(\"Uppercase:\", experiment.upper())\r\nprint(\"Lowercase:\", experiment.lower())\r\nprint(\"Title Case:\", experiment.title())\r\n\r\n\r\nprint(\"\\n========== 6. REMOVING SPACES ==========\")\r\n\r\nraw_data = \"   9.81 m/s^2   \"\r\nprint(\"Raw:\", raw_data)\r\nprint(\"Strip:\", raw_data.strip())\r\nprint(\"Left strip:\", raw_data.lstrip())\r\nprint(\"Right strip:\", raw_data.rstrip())\r\n\r\n\r\nprint(\"\\n========== 7. STRING CONCATENATION ==========\")\r\n\r\nquantity = \"Energy\"\r\nvalue = \"5.2\"\r\ncombined = quantity + \" = \" + value + \" \" + unit\r\nprint(combined)\r\n\r\n\r\nprint(\"\\n========== 8. STRING FORMATTING ==========\")\r\n\r\n# Using f-strings (recommended)\r\nmass = 2.0\r\nvelocity = 3.0\r\nprint(f\"Kinetic Energy depends on m = {mass} kg and v = {velocity} m/s\")\r\n\r\n# Using format()\r\nprint(\"Mass = {} kg, Velocity = {} m/s\".format(mass, velocity))\r\n\r\n\r\nprint(\"\\n========== 9. STRING REPLACEMENT ==========\")\r\n\r\nformula = \"E = mc2\"\r\nprint(\"Original:\", formula)\r\nprint(\"Corrected:\", formula.replace(\"2\", \"^2\"))\r\n\r\n\r\nprint(\"\\n========== 10. CHECKING SUBSTRINGS ==========\")\r\n\r\nsentence = \"Quantum mechanics is fundamental\"\r\nprint(\"Contains \'Quantum\'?\", \"Quantum\" in sentence)\r\nprint(\"Contains \'Classical\'?\", \"Classical\" in sentence)\r\n\r\n\r\nprint(\"\\n========== 11. COUNTING CHARACTERS ==========\")\r\n\r\ndata = \"aaaaabbbbcc\"\r\nprint(\"Count of \'a\':\", data.count(\"a\"))\r\nprint(\"Count of \'b\':\", data.count(\"b\"))\r\n\r\n\r\nprint(\"\\n========== 12. FINDING POSITION ==========\")\r\n\r\nequation = \"V = IR\"\r\nprint(\"Position of \'=\':\", equation.find(\"=\"))\r\nprint(\"Position of \'I\':\", equation.find(\"I\"))\r\n\r\n\r\nprint(\"\\n========== 13. STARTS WITH / ENDS WITH ==========\")\r\n\r\nfilename = \"experiment_data.csv\"\r\nprint(\"Starts with \'experiment\'?\", filename.startswith(\"experiment\"))\r\nprint(\"Ends with \'.csv\'?\", filename.endswith(\".csv\"))\r\n\r\n\r\nprint(\"\\n========== 14. SPLITTING STRINGS ==========\")\r\n\r\nmeasurement = \"10.5,20.3,15.8\"\r\nvalues = measurement.split(\",\")\r\nprint(\"Split values:\", values)\r\n\r\n\r\nprint(\"\\n========== 15. JOINING STRINGS ==========\")\r\n\r\njoined = \" | \".join(values)\r\nprint(\"Joined values:\", joined)\r\n\r\n\r\nprint(\"\\n========== 16. CHECKING STRING TYPE ==========\")\r\n\r\nnum_str = \"12345\"\r\nalpha_str = \"Physics\"\r\n\r\nprint(\"Is digit?\", num_str.isdigit())\r\nprint(\"Is alphabet?\", alpha_str.isalpha())\r\nprint(\"Is alphanumeric?\", \"E2\".isalnum())\r\n\r\n\r\nprint(\"\\n========== 17. MULTILINE STRINGS ==========\")\r\n\r\ntheory = \"\"\"\r\nNewton\'s Laws:\r\n1. Inertia\r\n2. F = ma\r\n3. Action = Reaction\r\n\"\"\"\r\nprint(theory)\r\n\r\n\r\nprint(\"\\n========== 18. ESCAPE CHARACTERS ==========\")\r\n\r\nprint(\"Line1\\nLine2\")\r\nprint(\"Tab\\tSeparated\")\r\nprint(\"Quote: \\\"Photon\\\"\")\r\n\r\n\r\nprint(\"\\n========== 19. STRING COMPARISON ==========\")\r\n\r\ns1 = \"laser\"\r\ns2 = \"LASER\"\r\n\r\nprint(\"Equal?\", s1 == s2)\r\nprint(\"Equal (case-insensitive)?\", s1.lower() == s2.lower())\r\n\r\n\r\nprint(\"\\n========== 20. LOOPING THROUGH STRING ==========\")\r\n\r\nsymbol = \"EMW\"\r\nfor ch in symbol:\r\n    print(\"Character:\", ch)\r\n\r\n\r\nprint(\"\\n========== 21. STRING REVERSAL ==========\")\r\n\r\nwave = \"sine\"\r\nprint(\"Reversed:\", wave[::-1])\r\n\r\n\r\nprint(\"\\n========== 22. PRACTICAL PHYSICS EXAMPLE ==========\")\r\n\r\n# Parsing a physics record\r\nrecord = \"Mass=2.5kg;Velocity=4.0m/s\"\r\nparts = record.split(\";\")\r\n\r\nfor item in parts:\r\n    print(item)\r\n\r\nprint(\"\\n========== END OF STRING OPERATIONS ==========\")\r\n', NULL, '');
